const ASSETS = {"app.js":"/* ====================== Rtl AI — منطق الواجهة ======================\n   وضعان:\n     local  → عبر خدمة opencode المحلية (جلسات + أدوات + أذونات)\n     direct → مباشرة مع بوابة OpenCode المجانية (دردشة، والمحادثات فالمتصفح)\n   ================================================================== */\n\nconst $ = (s) => document.querySelector(s);\nconst $$ = (s) => [...document.querySelectorAll(s)];\n\nconst LS = {\n  model: \"ocw.model\",\n  directModel: \"ocw.directModel\",\n  agent: \"ocw.agent\",\n  dir: \"ocw.dir\",\n  showAll: \"ocw.showAll\",\n  mode: \"ocw.mode\",\n  theme: \"ocw.theme\",\n  chats: \"ocw.chats\",\n  favs: \"ocw.favs\",\n};\n\nconst state = {\n  mode: localStorage.getItem(LS.mode) === \"direct\" ? \"direct\" : \"local\",\n  theme: localStorage.getItem(LS.theme) || \"system\",\n  health: null,\n  models: [],\n  agents: [],\n  sessions: [],\n  session: null,\n  messages: [],\n  deltas: new Map(),\n  permissions: [],\n  running: false,\n  sending: false,\n  usage: null,\n  toolsEnabled: false,\n  localAvailable: true,\n  modelFilter: \"free\",\n  favs: new Set(),\n  direct: { chats: [], current: null },\n};\n\nconst dom = {};\nlet renderQueued = false;\nlet refreshTimer = null;\nlet es = null;\nlet directAbort = null;\nlet toastTimer = null;\nlet recognizer = null;\n\n/* ------------------------------------------------------------------ أدوات */\n\nfunction el(tag, cls, text) {\n  const n = document.createElement(tag);\n  if (cls) n.className = cls;\n  if (text !== undefined && text !== null) n.textContent = text;\n  return n;\n}\n\nfunction escapeHtml(s) {\n  return String(s).replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\n}\n\nfunction renderMarkdown(text) {\n  const blocks = [];\n  let s = escapeHtml(text || \"\").replace(/\\r\\n/g, \"\\n\");\n  s = s.replace(/```[^\\n]*\\n?([\\s\\S]*?)```/g, (_m, code) => {\n    blocks.push(code.replace(/\\n$/, \"\"));\n    return `\\u0000${blocks.length - 1}\\u0000`;\n  });\n  s = s.replace(/`([^`\\n]+)`/g, \"<code>$1</code>\");\n  s = s.replace(/\\*\\*([^*\\n]+)\\*\\*/g, \"<strong>$1</strong>\");\n  s = s.replace(/(^|\\n)[-*] /g, \"$1• \");\n  s = s.replace(/(^|\\n)#{1,5} (.+)/g, \"$1<strong>$2</strong>\");\n  const html = s\n    .split(/\\n{2,}/)\n    .map((p) => `<p>${p.replace(/\\n/g, \"<br>\")}</p>`)\n    .join(\"\");\n  return html.replace(/\\u0000(\\d+)\\u0000/g, (_m, i) => `<pre><code>${blocks[Number(i)]}</code></pre>`);\n}\n\nfunction mdNode(text) {\n  const d = el(\"div\", \"md\");\n  d.innerHTML = renderMarkdown(text);\n  return d;\n}\n\nfunction sparkIcon() {\n  const d = el(\"div\", \"aispark\");\n  d.innerHTML =\n    '<svg viewBox=\"0 0 24 24\"><defs><linearGradient id=\"sp-g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">' +\n    '<stop offset=\"0\" stop-color=\"#4285F4\"/><stop offset=\".55\" stop-color=\"#9B72CB\"/><stop offset=\"1\" stop-color=\"#D96570\"/>' +\n    '</linearGradient></defs><path fill=\"url(#sp-g)\" d=\"M12 2l1.9 7.1L21 11l-7.1 1.9L12 20l-1.9-7.1L3 11l7.1-1.9z\"/></svg>';\n  return d;\n}\n\nfunction toast(message) {\n  dom.toast.textContent = message;\n  dom.toast.classList.remove(\"hidden\");\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(() => dom.toast.classList.add(\"hidden\"), 2600);\n}\n\nfunction timeAgo(ts) {\n  if (!ts) return \"\";\n  const diff = Date.now() - ts;\n  if (diff < 60_000) return \"الآن\";\n  const m = Math.floor(diff / 60_000);\n  if (m < 60) return `قبل ${m} د`;\n  const h = Math.floor(m / 60);\n  if (h < 24) return `قبل ${h} س`;\n  const d = Math.floor(h / 24);\n  if (d < 30) return `قبل ${d} ي`;\n  return new Date(ts).toLocaleDateString(\"ar\");\n}\n\nfunction baseName(p) {\n  if (!p) return \"\";\n  const parts = String(p).split(/[\\\\/]/).filter(Boolean);\n  return parts[parts.length - 1] || p;\n}\n\nfunction modelKey(m) {\n  return m ? `${m.providerID}/${m.id || m.modelID}` : \"\";\n}\n\nfunction currentModel() {\n  const v = dom.modelSelect.value;\n  if (!v) return null;\n  const i = v.indexOf(\"/\");\n  return { providerID: v.slice(0, i), id: v.slice(i + 1) };\n}\n\nconst isDirect = () => state.mode === \"direct\";\n\nfunction prettyCurrentModelName() {\n  const v = dom.modelSelect.value;\n  if (!v) return \"—\";\n  if (isDirect()) {\n    const f = state.models.find((m) => m.id === v);\n    return f ? f.name || f.id : v;\n  }\n  const found = state.models.find((m) => modelKey(m) === v);\n  return found ? found.name : v.slice(v.indexOf(\"/\") + 1);\n}\n\n/* قيمة النموذج داخل <select> (مختلفة بين الوضعين) */\nconst modelValue = (m) => (isDirect() ? m.id : modelKey(m));\n\n/* وسوم النموذج */\nfunction modelTags(m) {\n  const t = [];\n  if (m.free) t.push(\"مجاني\");\n  if (!isDirect()) {\n    if (m.reasoning) t.push(\"تفكير\");\n    if ((m.input || []).includes(\"image\")) t.push(\"صور\");\n    if (m.context) t.push(Math.round(m.context / 1000) + \"K سياق\");\n  }\n  if (m.status && m.status !== \"active\") t.push(m.status);\n  return t;\n}\n\n/* ------------------------------------------------------------------ الشبكة */\n\nasync function api(path, opts = {}) {\n  const res = await fetch(path, {\n    method: opts.method || \"GET\",\n    headers: opts.body !== undefined ? { \"Content-Type\": \"application/json\" } : undefined,\n    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,\n    signal: opts.signal,\n  });\n  const raw = await res.text();\n  let data = null;\n  try {\n    data = raw ? JSON.parse(raw) : null;\n  } catch {\n    data = { raw };\n  }\n  if (res.status === 401) {\n    showLogin();\n    throw new Error((data && data.error) || \"خاصك تسجل الدخول\");\n  }\n  if (!res.ok) throw new Error((data && (data.error || data.message)) || `HTTP ${res.status}`);\n  return data;\n}\n\nfunction showLogin() {\n  dom.login.classList.remove(\"hidden\");\n}\n\n/* ------------------------------------------------------------------ المظهر */\n\nfunction resolveTheme(pref) {\n  if (pref !== \"system\") return pref;\n  return window.matchMedia(\"(prefers-color-scheme: light)\").matches ? \"light\" : \"dark\";\n}\n\nfunction applyTheme(pref, save = true) {\n  state.theme = pref;\n  if (save) localStorage.setItem(LS.theme, pref);\n  const resolved = resolveTheme(pref);\n  document.documentElement.dataset.theme = resolved;\n\n  dom.themeIcon.innerHTML =\n    resolved === \"dark\"\n      ? '<path d=\"M21 12.8A9 9 0 1111.2 3a7 7 0 009.8 9.8z\"/>'\n      : '<circle cx=\"12\" cy=\"12\" r=\"4.2\"/><path d=\"M12 2v2.4M12 19.6V22M2 12h2.4M19.6 12H22M4.9 4.9l1.7 1.7M17.4 17.4l1.7 1.7M19.1 4.9l-1.7 1.7M6.6 17.4l-1.7 1.7\"/>';\n\n  $$(\"[data-theme]\").forEach((b) => {\n    if (b.tagName === \"BUTTON\" && b.classList.contains(\"preset\")) b.classList.toggle(\"on\", b.dataset.theme === pref);\n  });\n\n  // لون شريط النظام فالتطبيق المثبّت\n  const meta = document.querySelector('meta[name=\"theme-color\"]');\n  if (meta) meta.setAttribute(\"content\", resolved === \"dark\" ? \"#0c0d12\" : \"#f6f7fb\");\n}\n\n/* ------------------------------------------------------------------ التثبيت كتطبيق (PWA) */\n\nlet installPrompt = null;\n\nfunction setupPwa() {\n  // تسجيل عامل الخدمة (خاص HTTPS ولا localhost)\n  if (\"serviceWorker\" in navigator) {\n    window.addEventListener(\"load\", () => {\n      navigator.serviceWorker.register(\"/sw.js\").catch(() => {});\n    });\n  }\n\n  // أندرويد/كروم: كيبدا الحدث ملي الموقع يقدر يتثبّت\n  window.addEventListener(\"beforeinstallprompt\", (e) => {\n    e.preventDefault();\n    installPrompt = e;\n    dom.btnInstall.classList.remove(\"hidden\");\n  });\n\n  window.addEventListener(\"appinstalled\", () => {\n    installPrompt = null;\n    dom.btnInstall.classList.add(\"hidden\");\n    toast(\"تثبّت التطبيق ✅\");\n  });\n\n  dom.btnInstall.addEventListener(\"click\", async () => {\n    closeDrawer();\n    if (installPrompt) {\n      installPrompt.prompt();\n      const { outcome } = await installPrompt.userChoice;\n      if (outcome === \"accepted\") dom.btnInstall.classList.add(\"hidden\");\n      installPrompt = null;\n      return;\n    }\n    const isIos = /iphone|ipad|ipod/i.test(navigator.userAgent);\n    toast(\n      isIos\n        ? \"فـ iPhone: زر المشاركة ⬆️ ← «إضافة إلى الشاشة الرئيسية»\"\n        : \"افتح قائمة المتصفح (⋮) ← «تثبيت التطبيق» ولا «إضافة إلى الشاشة الرئيسية»\"\n    );\n  });\n\n  // اختصار «محادثة جديدة» من أيقونة التطبيق\n  if (new URLSearchParams(location.search).has(\"new\")) {\n    history.replaceState(null, \"\", location.pathname);\n    setTimeout(() => (isDirect() ? newDirectChat() : createSession()), 300);\n  }\n}\n\n/* ------------------------------------------------------------------ الحالة */\n\nasync function loadHealth() {\n  try {\n    const h = await api(\"/api/health\");\n    state.health = h;\n    state.localAvailable = h.localAvailable !== false;\n    state.toolsEnabled = false;\n    if (h.ready) {\n      dom.statusPill.textContent = `متصل • v${h.version}`;\n      dom.statusPill.className = \"pill ok\";\n      dom.statusDetail.textContent = \"خدمة opencode المحلية\";\n    } else {\n      dom.statusPill.textContent = \"تعذّر الاتصال\";\n      dom.statusPill.className = \"pill bad\";\n      dom.statusDetail.textContent = h.server ? `المنفذ ${h.server}` : \"شغّل opencode\";\n    }\n    if (!dom.dirInput.value) dom.dirInput.value = localStorage.getItem(LS.dir) || h.location || \"\";\n    renderStatusBadge();\n  } catch (err) {\n    dom.statusPill.textContent = \"خطأ: \" + err.message;\n    dom.statusPill.className = \"pill bad\";\n  }\n}\n\nasync function loadDirectStatus() {\n  try {\n    const st = await api(\"/api/direct/status\");\n    state.toolsEnabled = (st.tools || []).length > 0;\n    dom.statusPill.textContent = st.reachable ? \"بوابة مجانية ✅\" : \"البوابة ما رجعتش\";\n    dom.statusPill.className = \"pill \" + (st.reachable ? \"ok\" : \"bad\");\n    dom.statusDetail.textContent = st.base.replace(\"https://\", \"\");\n    if (st.base) dom.gatewayUrl.textContent = st.base;\n    renderDirectNote(st.tools || []);\n    renderStatusBadge();\n    renderFieldVisibility();\n    return st;\n  } catch (err) {\n    dom.statusPill.textContent = \"خطأ: \" + err.message;\n    dom.statusPill.className = \"pill bad\";\n    return null;\n  }\n}\n\nfunction renderDirectNote(tools) {\n  dom.directNote.classList.remove(\"hidden\");\n  if (tools.length) {\n    dom.directNote.innerHTML =\n      \"وضع <b>مباشر + أدوات</b>: كيهدر مباشرة مع بوابة OpenCode المجانية. \" +\n      \"الأدوات (<code>read/write/bash</code>) كتنفذ على <b>السيرفر</b>، ماشي على الحاسوب ديالك.\";\n    return;\n  }\n  dom.directNote.innerHTML =\n    \"وضع <b>مباشر — دردشة فقط</b>: كيهدر مباشرة مع بوابة OpenCode المجانية، بلا حاجة للحاسوب ديالك وبلا أي وصول للملفات.<br>\" +\n    \"ملاحظة: عميل غير رسمي، يمكن يتحجب فأي وقت، وعندو حصة مجانية محدودة.\";\n}\n\nfunction renderStatusBadge() {\n  const badge = dom.wsBadge;\n  if (isDirect()) {\n    badge.textContent = state.toolsEnabled ? \"مباشر • أدوات\" : \"مباشر • دردشة فقط\";\n    badge.className = \"pill ok\";\n    dom.wsDetail.textContent = \"بوابة OpenCode المجانية — ما كيحتاجش الحاسوب ديالك.\";\n    return;\n  }\n  if (state.health?.ready) {\n    badge.textContent = \"متصل بخدمة opencode\";\n    badge.className = \"pill ok\";\n    dom.wsDetail.textContent = state.health.location || \"\";\n  } else {\n    badge.textContent = \"غير متصل\";\n    badge.className = \"pill bad\";\n    dom.wsDetail.textContent = \"شغّل opencode من بعد حدّث الصفحة.\";\n  }\n}\n\nfunction renderFieldVisibility() {\n  dom.agentField.classList.toggle(\"hidden\", isDirect());\n  dom.dirField.classList.toggle(\"hidden\", isDirect() && !state.toolsEnabled);\n  dom.showAll.closest(\".check\").classList.toggle(\"hidden\", isDirect());\n}\n\n/* ------------------------------------------------------------------ النماذج */\n\nasync function loadModels() {\n  if (isDirect()) {\n    try {\n      const { models } = await api(\"/api/direct/models\");\n      state.models = models;\n    } catch (err) {\n      console.error(err);\n      state.models = [];\n    }\n  } else {\n    const dir = dom.dirInput.value.trim();\n    try {\n      const { models } = await api(\"/api/models\" + (dir ? `?directory=${encodeURIComponent(dir)}` : \"\"));\n      state.models = models;\n    } catch (err) {\n      console.error(err);\n      state.models = [];\n    }\n  }\n  renderModelSelect();\n}\n\nfunction renderModelSelect() {\n  const previous = dom.modelSelect.value || localStorage.getItem(isDirect() ? LS.directModel : LS.model) || \"\";\n  const showAll = dom.showAll.checked;\n  const list = isDirect() ? state.models : state.models.filter((m) => m.enabled && (showAll || m.free));\n\n  dom.modelSelect.textContent = \"\";\n  if (!list.length) dom.modelSelect.appendChild(new Option(\"لا توجد نماذج\", \"\"));\n\n  for (const m of list) {\n    const value = isDirect() ? m.id : modelKey(m);\n    const label = isDirect() ? m.id : `${m.name}${m.free ? \" — مجاني ✓\" : \" — يحتاج مفتاح\"}`;\n    dom.modelSelect.appendChild(new Option(label, value));\n  }\n  if (previous && ![...dom.modelSelect.options].some((o) => o.value === previous)) {\n    dom.modelSelect.appendChild(new Option(previous, previous));\n  }\n  const firstFree = state.models.find((m) => m.free) || state.models[0];\n  dom.modelSelect.value = previous || (firstFree ? modelValue(firstFree) : \"\");\n  localStorage.setItem(isDirect() ? LS.directModel : LS.model, dom.modelSelect.value);\n  updateHeader();\n  renderModelList();\n}\n\n/* ------------------------------------------------------------------ اختيار النموذج */\n\nfunction renderModelList() {\n  if (!dom.modelList) return;\n  const box = dom.modelList;\n  box.textContent = \"\";\n\n  const q = dom.modelSearch.value.trim().toLowerCase();\n  const current = dom.modelSelect.value;\n  const source = state.models.filter((m) => (isDirect() ? true : m.enabled !== false));\n\n  let list = source;\n  if (state.modelFilter === \"fav\") list = list.filter((m) => state.favs.has(modelValue(m)));\n  else if (state.modelFilter === \"free\") list = list.filter((m) => m.free);\n  if (q) list = list.filter((m) => `${m.id} ${m.name || \"\"} ${m.family || \"\"}`.toLowerCase().includes(q));\n\n  const favCount = source.filter((m) => state.favs.has(modelValue(m))).length;\n  dom.modelCount.textContent = `${list.length} من ${source.length} نموذج${favCount ? ` • ${favCount} مفضّل` : \"\"}`;\n\n  if (!list.length) {\n    box.appendChild(\n      el(\"div\", \"muted\", source.length ? \"ما كاينش نتيجة. بدّل الفلتر ولا البحث.\" : \"ما تحمّلو حتى نموذج — دير تحديث.\")\n    );\n    return;\n  }\n\n  for (const m of list) {\n    const value = modelValue(m);\n    const row = el(\"div\", \"mitem\" + (value === current ? \" active\" : \"\"));\n\n    const info = el(\"div\", \"minfo\");\n    info.appendChild(el(\"div\", \"mname\", m.name || m.id));\n    info.appendChild(el(\"div\", \"mid\", m.id));\n    const tags = el(\"div\", \"mtags\");\n    for (const t of modelTags(m)) {\n      const cls = t === \"مجاني\" ? \"mtag free\" : t === \"أدوات\" ? \"mtag tools\" : \"mtag\";\n      tags.appendChild(el(\"span\", cls, t));\n    }\n    info.appendChild(tags);\n    row.appendChild(info);\n\n    const fav = state.favs.has(value);\n    const star = el(\"button\", \"star\" + (fav ? \" on\" : \"\"), fav ? \"★\" : \"☆\");\n    star.title = fav ? \"حيّد من المفضلة\" : \"زيد للمفضلة\";\n    star.addEventListener(\"click\", (e) => {\n      e.stopPropagation();\n      if (state.favs.has(value)) state.favs.delete(value);\n      else state.favs.add(value);\n      localStorage.setItem(LS.favs, JSON.stringify([...state.favs]));\n      renderModelList();\n    });\n    row.appendChild(star);\n\n    row.appendChild(el(\"span\", \"mcheck\", value === current ? \"✓\" : \"\"));\n\n    row.addEventListener(\"click\", () => {\n      dom.modelSelect.value = value;\n      applyModelChange();\n      closeModels();\n      toast(\"النموذج: \" + (m.name || m.id));\n    });\n\n    box.appendChild(row);\n  }\n}\n\nfunction openModels() {\n  closeDrawer();\n  dom.modelSearch.value = \"\";\n  renderModelList();\n  dom.models.classList.add(\"open\");\n  setTimeout(() => dom.modelSearch.focus(), 250);\n}\n\nfunction closeModels() {\n  dom.models.classList.remove(\"open\");\n}\n\nasync function applyModelChange() {\n  const value = dom.modelSelect.value;\n  localStorage.setItem(isDirect() ? LS.directModel : LS.model, value);\n  updateHeader();\n  dom.pickModelName.textContent = prettyCurrentModelName();\n\n  if (isDirect()) {\n    const chat = currentChat();\n    if (chat) {\n      chat.model = value;\n      saveDirectChats();\n    }\n    return;\n  }\n  if (!state.session) return;\n  try {\n    await api(`/api/sessions/${encodeURIComponent(state.session.id)}/model`, {\n      method: \"POST\",\n      body: { model: currentModel() },\n    });\n  } catch (err) {\n    toast(\"تعذّر تغيير النموذج: \" + err.message);\n  }\n}\n\nasync function loadAgents() {\n  try {\n    const { agents } = await api(\"/api/agents\");\n    state.agents = agents;\n  } catch {\n    state.agents = [{ id: \"build\", name: \"Build\" }];\n  }\n  const previous = localStorage.getItem(LS.agent) || \"build\";\n  dom.agentSelect.textContent = \"\";\n  for (const a of state.agents) dom.agentSelect.appendChild(new Option(a.name, a.id));\n  dom.agentSelect.value = state.agents.some((a) => a.id === previous) ? previous : state.agents[0]?.id || \"build\";\n}\n\n/* ------------------------------------------------------------------ الوضع المباشر */\n\nfunction loadDirectChats() {\n  try {\n    const raw = JSON.parse(localStorage.getItem(LS.chats) || \"[]\");\n    state.direct.chats = Array.isArray(raw) ? raw : [];\n  } catch {\n    state.direct.chats = [];\n  }\n}\n\nfunction saveDirectChats() {\n  try {\n    const trimmed = state.direct.chats.slice(0, 80).map((c) => ({\n      ...c,\n      items: c.items.slice(-150).map((it) =>\n        it.kind === \"user\"\n          ? it\n          : {\n              ...it,\n              text: (it.text || \"\").slice(0, 40000),\n              reasoning: (it.reasoning || \"\").slice(0, 20000),\n              tools: (it.tools || []).map((t) => ({ ...t, output: (t.output || \"\").slice(0, 12000) })),\n            }\n      ),\n    }));\n    localStorage.setItem(LS.chats, JSON.stringify(trimmed));\n  } catch {\n    /* الذاكرة ممتلئة */\n  }\n}\n\nconst currentChat = () => state.direct.current;\n\nfunction newDirectChat() {\n  const chat = {\n    id: \"dc_\" + Date.now().toString(36),\n    title: \"محادثة جديدة\",\n    model: dom.modelSelect.value || \"\",\n    workspace: dom.dirInput.value.trim() || \"\",\n    created: Date.now(),\n    updated: Date.now(),\n    items: [],\n  };\n  state.direct.chats.unshift(chat);\n  state.direct.current = chat;\n  saveDirectChats();\n  return chat;\n}\n\nfunction directHistory(chat) {\n  const out = [];\n  for (const it of chat.items) {\n    if (it.kind === \"user\") {\n      out.push({ role: \"user\", content: it.text });\n      continue;\n    }\n    const msg = { role: \"assistant\", content: it.text || null };\n    if (it.tools?.length) {\n      msg.tool_calls = it.tools.map((t) => ({\n        id: t.id,\n        type: \"function\",\n        function: { name: t.name, arguments: JSON.stringify(t.input || {}) },\n      }));\n    }\n    if (!msg.content && !msg.tool_calls) msg.content = \"\";\n    out.push(msg);\n    for (const t of it.tools || []) {\n      out.push({ role: \"tool\", tool_call_id: t.id, content: t.output || t.error || \"(بدون نتيجة)\" });\n    }\n  }\n  return out;\n}\n\nfunction directToRender(chat) {\n  if (!chat) return [];\n  const out = [];\n  chat.items.forEach((it, i) => {\n    if (it.kind === \"user\") {\n      out.push({ id: \"d\" + i, type: \"user\", text: it.text });\n      return;\n    }\n    const content = [];\n    if (it.reasoning) content.push({ type: \"reasoning\", text: it.reasoning });\n    if (it.text) content.push({ type: \"text\", text: it.text });\n    for (const t of it.tools || []) {\n      content.push({\n        type: \"tool\",\n        id: t.id,\n        name: t.name,\n        state: {\n          status: t.status,\n          input: t.input,\n          content: t.output ? [{ type: \"text\", text: t.output }] : undefined,\n          error: t.error ? { type: \"error\", message: t.error } : undefined,\n        },\n      });\n    }\n    if (it.error) content.push({ type: \"error\", text: it.error });\n    out.push({\n      id: \"d\" + i,\n      type: \"assistant\",\n      content,\n      agent: \"\",\n      model: { id: it.model || chat.model, providerID: \"opencode\" },\n      tokens: it.usage\n        ? {\n            input: it.usage.prompt_tokens ?? it.usage.input,\n            output: it.usage.completion_tokens ?? it.usage.output,\n            reasoning: it.usage.reasoning_tokens || 0,\n          }\n        : null,\n      cost: 0,\n    });\n  });\n  return out;\n}\n\n/* ------------------------------------------------------------------ القوائم */\n\nasync function loadSessions() {\n  if (isDirect()) return renderDirectList();\n  const search = dom.sessionSearch.value.trim();\n  const params = new URLSearchParams({ limit: \"60\", parentID: \"null\" });\n  if (search) params.set(\"search\", search);\n  try {\n    const { sessions } = await api(\"/api/sessions?\" + params.toString());\n    state.sessions = sessions;\n  } catch {\n    state.sessions = [];\n  }\n  renderSessionList();\n}\n\nfunction renderSessionList() {\n  if (isDirect()) return renderDirectList();\n  const box = dom.sessionList;\n  box.textContent = \"\";\n  if (!state.sessions.length) {\n    box.appendChild(el(\"div\", \"muted\", \"لا توجد محادثات بعد.\"));\n    return;\n  }\n  for (const s of state.sessions) {\n    const item = el(\"div\", \"session-item\" + (state.session && state.session.id === s.id ? \" active\" : \"\"));\n    item.appendChild(el(\"span\", \"t\", s.title || \"بدون عنوان\"));\n    const sub = el(\"span\", \"s\");\n    sub.appendChild(el(\"span\", null, s.model ? s.model.id : \"—\"));\n    if (s.directory) sub.appendChild(el(\"span\", null, \"• \" + baseName(s.directory)));\n    sub.appendChild(el(\"span\", null, \"• \" + timeAgo(s.updated || s.created)));\n    if (s.cost === 0) sub.appendChild(el(\"span\", \"tag-free\", \"• مجاني\"));\n    item.appendChild(sub);\n\n    const del = el(\"button\", \"del\", \"🗑\");\n    del.title = \"حذف\";\n    del.addEventListener(\"click\", async (ev) => {\n      ev.stopPropagation();\n      if (!confirm(\"حذف هذه المحادثة؟\")) return;\n      await api(`/api/sessions/${encodeURIComponent(s.id)}`, { method: \"DELETE\" });\n      if (state.session && state.session.id === s.id) newChat();\n      loadSessions();\n      toast(\"تحذفات المحادثة\");\n    });\n    item.appendChild(del);\n    item.addEventListener(\"click\", () => openSession(s.id));\n    box.appendChild(item);\n  }\n}\n\nfunction renderDirectList() {\n  const box = dom.sessionList;\n  box.textContent = \"\";\n  const search = dom.sessionSearch.value.trim().toLowerCase();\n  const chats = state.direct.chats.filter((c) => !search || c.title.toLowerCase().includes(search));\n  if (!chats.length) {\n    box.appendChild(el(\"div\", \"muted\", \"لا توجد محادثات بعد.\"));\n    return;\n  }\n  for (const c of chats) {\n    const item = el(\"div\", \"session-item\" + (currentChat()?.id === c.id ? \" active\" : \"\"));\n    item.appendChild(el(\"span\", \"t\", c.title));\n    const sub = el(\"span\", \"s\");\n    sub.appendChild(el(\"span\", null, c.model || \"—\"));\n    if (c.workspace) sub.appendChild(el(\"span\", null, \"• \" + baseName(c.workspace)));\n    sub.appendChild(el(\"span\", null, \"• \" + timeAgo(c.updated)));\n    item.appendChild(sub);\n\n    const del = el(\"button\", \"del\", \"🗑\");\n    del.title = \"حذف\";\n    del.addEventListener(\"click\", (ev) => {\n      ev.stopPropagation();\n      if (!confirm(\"حذف هذه المحادثة؟\")) return;\n      state.direct.chats = state.direct.chats.filter((x) => x.id !== c.id);\n      if (currentChat()?.id === c.id) state.direct.current = null;\n      saveDirectChats();\n      renderMessages();\n      renderDirectList();\n      toast(\"تحذفات المحادثة\");\n    });\n    item.appendChild(del);\n\n    item.addEventListener(\"click\", () => {\n      state.direct.current = c;\n      if (c.model && [...dom.modelSelect.options].some((o) => o.value === c.model)) dom.modelSelect.value = c.model;\n      if (c.workspace) dom.dirInput.value = c.workspace;\n      updateHeader();\n      renderMessages();\n      renderDirectList();\n      closeDrawer();\n    });\n    box.appendChild(item);\n  }\n}\n\n/* ------------------------------------------------------------------ العرض */\n\nconst currentMessages = () => (isDirect() ? directToRender(currentChat()) : state.messages);\n\nfunction reasoningNode(text) {\n  const d = document.createElement(\"details\");\n  d.className = \"reasoning\";\n  const s = document.createElement(\"summary\");\n  s.textContent = \"سلسلة التفكير\";\n  d.appendChild(s);\n  d.appendChild(el(\"pre\", null, text));\n  return d;\n}\n\nconst statusLabel = (st) =>\n  st === \"completed\" ? \"انتهى\" : st === \"error\" ? \"خطأ\" : st === \"running\" ? \"يعمل…\" : st || \"\";\n\nfunction toolInputSummary(input) {\n  if (!input || typeof input !== \"object\") return \"\";\n  for (const k of [\"command\", \"filePath\", \"path\", \"pattern\", \"query\", \"url\", \"description\", \"prompt\"]) {\n    if (typeof input[k] === \"string\" && input[k].trim()) {\n      const v = input[k].replace(/\\s+/g, \" \").trim();\n      return v.length > 60 ? v.slice(0, 60) + \"…\" : v;\n    }\n  }\n  const first = Object.values(input).find((v) => typeof v === \"string\" && v.trim());\n  return first ? String(first).slice(0, 60) : \"\";\n}\n\nfunction toolNode(part) {\n  const st = part.state || {};\n  const status = st.status || \"running\";\n  const d = document.createElement(\"details\");\n  d.className = \"tool\";\n\n  const head = document.createElement(\"summary\");\n  head.className = \"tool-head\";\n  head.appendChild(el(\"span\", \"name\", part.name || \"tool\"));\n  head.appendChild(el(\"span\", \"badge \" + status, statusLabel(status)));\n  const hint = toolInputSummary(st.input);\n  if (hint) head.appendChild(el(\"span\", \"muted\", hint));\n  d.appendChild(head);\n\n  if (st.input && Object.keys(st.input).length) d.appendChild(el(\"pre\", null, JSON.stringify(st.input, null, 2)));\n  if (Array.isArray(st.content)) {\n    for (const c of st.content) {\n      if (c.type === \"text\") d.appendChild(el(\"pre\", null, c.text));\n      else if (c.type === \"file\") d.appendChild(el(\"pre\", null, `📄 ${c.name || c.uri}`));\n    }\n  }\n  if (st.error) d.appendChild(el(\"pre\", null, `${st.error.type || \"خطأ\"}: ${st.error.message || \"\"}`));\n  if (status === \"running\") d.open = true;\n  return d;\n}\n\nfunction assistantNodes(msg) {\n  const nodes = [];\n  const counters = { text: 0, reasoning: 0 };\n  const seen = { text: new Set(), reasoning: new Set() };\n\n  for (const part of msg.content || []) {\n    if (part.type === \"reasoning\") {\n      const i = counters.reasoning++;\n      seen.reasoning.add(i);\n      const delta = state.deltas.get(`${msg.id}:reasoning:${i}`);\n      nodes.push(reasoningNode(delta && delta.length > (part.text || \"\").length ? delta : part.text || \"\"));\n    } else if (part.type === \"text\") {\n      const i = counters.text++;\n      seen.text.add(i);\n      const delta = state.deltas.get(`${msg.id}:text:${i}`);\n      nodes.push(mdNode(delta && delta.length > (part.text || \"\").length ? delta : part.text || \"\"));\n    } else if (part.type === \"tool\") {\n      nodes.push(toolNode(part));\n    } else if (part.type === \"error\") {\n      nodes.push(el(\"div\", \"error-box\", part.text));\n    }\n  }\n\n  for (const [key, text] of state.deltas) {\n    if (!key.startsWith(msg.id + \":\")) continue;\n    const [, type, idxRaw] = key.split(\":\");\n    const idx = Number(idxRaw);\n    if (type === \"text\" && !seen.text.has(idx)) nodes.push(mdNode(text));\n    if (type === \"reasoning\" && !seen.reasoning.has(idx)) nodes.push(reasoningNode(text));\n  }\n  return nodes;\n}\n\nfunction actionBar(msg) {\n  const bar = el(\"div\", \"actions\");\n\n  const copy = el(\"button\", \"a\");\n  copy.title = \"نسخ\";\n  copy.innerHTML = '<svg viewBox=\"0 0 24 24\"><rect x=\"9\" y=\"9\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M5 15V5a2 2 0 012-2h10\"/></svg>';\n  copy.addEventListener(\"click\", async () => {\n    const text = (msg.content || []).filter((p) => p.type === \"text\").map((p) => p.text).join(\"\\n\");\n    try {\n      await navigator.clipboard.writeText(text);\n      toast(\"تنسخ\");\n    } catch {\n      toast(\"تعذّر النسخ\");\n    }\n  });\n  bar.appendChild(copy);\n\n  if (isDirect() && msg.type === \"assistant\") {\n    const again = el(\"button\", \"a\");\n    again.title = \"عاود\";\n    again.innerHTML = '<svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 11-3-6.7M21 4v5h-5\"/></svg>';\n    again.addEventListener(\"click\", () => regenerate());\n    bar.appendChild(again);\n  }\n  return bar;\n}\n\nfunction messageNode(msg, isLast) {\n  if (msg.type === \"user\") {\n    const row = el(\"div\", \"userrow\");\n    row.appendChild(el(\"div\", \"bubble\", msg.text || \"\"));\n    return row;\n  }\n\n  const row = el(\"div\", \"airow\");\n  row.appendChild(sparkIcon());\n  const wrap = el(\"div\", \"aicontent\");\n\n  const label = [msg.model?.id || \"\", msg.agent || \"\"].filter(Boolean).join(\" • \");\n  if (label) wrap.appendChild(el(\"div\", \"role\", label));\n\n  for (const n of assistantNodes(msg)) wrap.appendChild(n);\n\n  if (state.running && isLast) {\n    const t = el(\"div\", \"typing\");\n    t.append(el(\"span\", null, \"يكتب\"), el(\"i\"), el(\"i\"), el(\"i\"));\n    wrap.appendChild(t);\n  }\n\n  wrap.appendChild(actionBar(msg));\n  row.appendChild(wrap);\n  return row;\n}\n\nfunction renderMessages() {\n  renderQueued = false;\n  const messages = currentMessages();\n  const box = dom.messages;\n  const nearBottom = isNearBottom();\n\n  if (!messages.length) {\n    dom.viewWelcome.classList.remove(\"hidden\");\n    dom.viewChat.classList.add(\"hidden\");\n    box.textContent = \"\";\n    renderStatusBadge();\n    return;\n  }\n\n  dom.viewWelcome.classList.add(\"hidden\");\n  dom.viewChat.classList.remove(\"hidden\");\n\n  box.textContent = \"\";\n  const lastIdx = [...messages].reverse().findIndex((m) => m.type === \"assistant\");\n  const lastId = lastIdx >= 0 ? messages[messages.length - 1 - lastIdx].id : null;\n  for (const m of messages) box.appendChild(messageNode(m, m.type === \"assistant\" && m.id === lastId));\n\n  if (nearBottom) scrollToBottom(false);\n}\n\nfunction queueRender() {\n  if (renderQueued) return;\n  renderQueued = true;\n  requestAnimationFrame(renderMessages);\n}\n\nfunction isNearBottom() {\n  const b = dom.messages;\n  return b.scrollHeight - b.scrollTop - b.clientHeight < 160;\n}\n\nfunction scrollToBottom(force) {\n  const b = dom.messages;\n  if (force || isNearBottom()) b.scrollTop = b.scrollHeight;\n}\n\nfunction updateHeader() {\n  const name = prettyCurrentModelName();\n  dom.chipModel.textContent = name;\n  if (dom.pickModelName) dom.pickModelName.textContent = name;\n}\n\nfunction updateRunningUi() {\n  dom.btnStop.classList.toggle(\"hidden\", !state.running);\n  dom.btnSend.classList.toggle(\"hidden\", state.running);\n  dom.btnSend.disabled = state.sending;\n}\n\n/* ------------------------------------------------------------------ التنقل */\n\nfunction openDrawer() {\n  dom.drawer.classList.add(\"open\");\n  dom.scrim.classList.remove(\"hidden\");\n  dom.drawer.setAttribute(\"aria-hidden\", \"false\");\n}\n\nfunction closeDrawer() {\n  dom.drawer.classList.remove(\"open\");\n  dom.scrim.classList.add(\"hidden\");\n  dom.drawer.setAttribute(\"aria-hidden\", \"true\");\n}\n\nfunction openSettings() {\n  closeDrawer();\n  dom.settings.classList.add(\"open\");\n}\n\nfunction closeSettings() {\n  dom.settings.classList.remove(\"open\");\n}\n\n/* ------------------------------------------------------------------ الأذونات */\n\nasync function loadPermissions() {\n  if (isDirect() || !state.session) return;\n  try {\n    const { permissions } = await api(`/api/sessions/${encodeURIComponent(state.session.id)}/permissions`);\n    state.permissions = permissions || [];\n  } catch {\n    state.permissions = [];\n  }\n  renderPermissions();\n}\n\nfunction renderPermissions() {\n  const box = dom.permissions;\n  box.textContent = \"\";\n  if (isDirect() || !state.permissions.length) {\n    box.classList.add(\"hidden\");\n    return;\n  }\n  box.classList.remove(\"hidden\");\n  for (const perm of state.permissions) {\n    const card = el(\"div\", \"permission-card\");\n    card.appendChild(el(\"span\", null, \"🔐 طلب إذن:\"));\n    card.appendChild(el(\"b\", null, perm.action));\n    const res = perm.resources?.[0] || \"\";\n    card.appendChild(el(\"code\", null, res.length > 60 ? res.slice(0, 60) + \"…\" : res));\n    for (const [decision, label] of [[\"once\", \"سماح\"], [\"always\", \"دائماً\"], [\"reject\", \"رفض\"]]) {\n      const b = el(\"button\", \"btn\" + (decision === \"reject\" ? \" danger\" : \" primary\"), label);\n      b.addEventListener(\"click\", async () => {\n        await api(\n          `/api/sessions/${encodeURIComponent(state.session.id)}/permissions/${encodeURIComponent(perm.id)}/reply`,\n          { method: \"POST\", body: { decision } }\n        );\n        await loadPermissions();\n      });\n      card.appendChild(b);\n    }\n    box.appendChild(card);\n  }\n}\n\n/* ------------------------------------------------------------------元神 البثّ */\n\nfunction appendDelta(key, delta) {\n  if (!delta) return;\n  state.deltas.set(key, (state.deltas.get(key) || \"\") + delta);\n  queueRender();\n}\n\nfunction scheduleRefresh(delay = 400) {\n  clearTimeout(refreshTimer);\n  refreshTimer = setTimeout(refreshMessages, delay);\n}\n\nasync function refreshMessages() {\n  if (isDirect() || !state.session) return;\n  try {\n    const { messages } = await api(`/api/sessions/${encodeURIComponent(state.session.id)}/messages`);\n    state.messages = messages;\n    for (const [key] of state.deltas) {\n      const [id, type, idxRaw] = key.split(\":\");\n      const idx = Number(idxRaw);\n      const msg = messages.find((m) => m.id === id);\n      let found = \"\";\n      if (msg && Array.isArray(msg.content)) {\n        let seen = 0;\n        for (const part of msg.content) {\n          if (part.type !== type) continue;\n          if (seen === idx) {\n            found = part.text || \"\";\n            break;\n          }\n          seen++;\n        }\n      }\n      if (found.length >= (state.deltas.get(key) || \"\").length) state.deltas.delete(key);\n    }\n    queueRender();\n  } catch (err) {\n    console.error(err);\n  }\n}\n\nfunction handleEvent(ev) {\n  const type = ev?.type || \"\";\n  const data = ev?.data || {};\n  const active = !isDirect() && state.session && data.sessionID === state.session.id;\n  if (!active && !type.startsWith(\"server\") && !type.startsWith(\"gateway\")) return;\n\n  switch (type) {\n    case \"session.text.delta\":\n      return appendDelta(`${data.assistantMessageID}:text:${data.ordinal}`, data.delta);\n    case \"session.reasoning.delta\":\n      return appendDelta(`${data.assistantMessageID}:reasoning:${data.ordinal}`, data.delta);\n    case \"session.execution.started\":\n      state.running = true;\n      updateRunningUi();\n      return queueRender();\n    case \"session.execution.succeeded\":\n    case \"session.execution.failed\":\n    case \"session.execution.interrupted\":\n      state.running = false;\n      updateRunningUi();\n      loadSessions();\n      refreshSessionMeta();\n      setTimeout(refreshSessionMeta, 3000);\n      return scheduleRefresh(200);\n    case \"session.usage.updated\":\n      state.usage = { cost: data.cost, tokens: data.tokens };\n      return;\n    case \"session.permission.created\":\n    case \"session.permission.updated\":\n      return loadPermissions();\n    default:\n      break;\n  }\n\n  if (!active) return;\n  if (type === \"session.inbox.enqueued\" || type.startsWith(\"session.tool\") || type === \"session.step.started\") {\n    scheduleRefresh(300);\n  } else if (type !== \"session.step.streamed\") {\n    scheduleRefresh(700);\n  }\n}\n\nfunction connectEvents() {\n  if (es) es.close();\n  es = new EventSource(\"/api/events\");\n  es.onmessage = (e) => {\n    try {\n      handleEvent(JSON.parse(e.data));\n    } catch {\n      /* تجاهل */\n    }\n  };\n}\n\nfunction startPolling() {\n  setInterval(() => {\n    if (!isDirect() && state.running) refreshMessages();\n  }, 1500);\n  setInterval(() => {\n    if (!isDirect() && state.running) loadPermissions();\n  }, 2000);\n  setInterval(() => {\n    if (!isDirect() && !state.health?.ready) loadHealth();\n  }, 12000);\n}\n\nasync function refreshSessionMeta() {\n  if (isDirect() || !state.session) return;\n  try {\n    const { session } = await api(`/api/sessions/${encodeURIComponent(state.session.id)}`);\n    if (session && state.session && session.id === state.session.id) {\n      state.session = session;\n      if (session.tokens) state.usage = { cost: session.cost, tokens: session.tokens };\n    }\n  } catch {\n    /* تجاهل */\n  }\n}\n\n/* ------------------------------------------------------------------ الجلسات */\n\nasync function createSession() {\n  const { session } = await api(\"/api/sessions\", {\n    method: \"POST\",\n    body: {\n      model: currentModel(),\n      agent: dom.agentSelect.value,\n      directory: dom.dirInput.value.trim() || undefined,\n    },\n  });\n  state.session = session;\n  state.messages = [];\n  state.deltas.clear();\n  state.usage = null;\n  return session;\n}\n\nasync function openSession(id) {\n  try {\n    const [{ session }, { messages }] = await Promise.all([\n      api(`/api/sessions/${encodeURIComponent(id)}`),\n      api(`/api/sessions/${encodeURIComponent(id)}/messages`),\n    ]);\n    state.session = session;\n    state.messages = messages;\n    state.deltas.clear();\n    state.usage = session.tokens ? { cost: session.cost, tokens: session.tokens } : null;\n    state.running = !session.time?.idle;\n    state.permissions = [];\n    if (session.model) {\n      const key = modelKey(session.model);\n      if (![...dom.modelSelect.options].some((o) => o.value === key)) {\n        dom.modelSelect.appendChild(new Option(session.model.id, key));\n      }\n      dom.modelSelect.value = key;\n      updateHeader();\n    }\n    if (session.agent && [...dom.agentSelect.options].some((o) => o.value === session.agent)) {\n      dom.agentSelect.value = session.agent;\n    }\n    if (session.location?.directory) dom.dirInput.value = session.location.directory;\n    closeDrawer();\n    renderMessages();\n    renderSessionList();\n    updateRunningUi();\n    await loadPermissions();\n    scrollToBottom(true);\n  } catch (err) {\n    toast(\"تعذّر فتح المحادثة: \" + err.message);\n  }\n}\n\nfunction newChat() {\n  if (isDirect()) {\n    state.direct.current = null;\n    renderMessages();\n    renderDirectList();\n    closeDrawer();\n    dom.input.focus();\n    return;\n  }\n  state.session = null;\n  state.messages = [];\n  state.deltas.clear();\n  state.usage = null;\n  state.running = false;\n  state.permissions = [];\n  renderPermissions();\n  updateRunningUi();\n  renderMessages();\n  renderSessionList();\n  closeDrawer();\n  dom.input.focus();\n}\n\n/* ------------------------------------------------------------------ الإرسال */\n\nfunction autoGrow() {\n  const t = dom.input;\n  t.style.height = \"auto\";\n  t.style.height = Math.min(t.scrollHeight, 180) + \"px\";\n}\n\nasync function sendMessage() {\n  const text = dom.input.value.trim();\n  if (!text || state.running || state.sending) return;\n  if (isDirect()) return sendDirect(text);\n\n  state.sending = true;\n  updateRunningUi();\n  try {\n    if (!state.session) await createSession();\n    dom.input.value = \"\";\n    autoGrow();\n\n    state.messages.push({ id: \"local-\" + Date.now(), type: \"user\", text, time: { created: Date.now() } });\n    state.running = true;\n    updateRunningUi();\n    renderMessages();\n    scrollToBottom(true);\n\n    await api(`/api/sessions/${encodeURIComponent(state.session.id)}/prompt`, { method: \"POST\", body: { text } });\n    scheduleRefresh(400);\n  } catch (err) {\n    state.running = false;\n    toast(\"تعذّر الإرسال: \" + err.message);\n  } finally {\n    state.sending = false;\n    updateRunningUi();\n  }\n}\n\nasync function sendDirect(text) {\n  const chat = currentChat() || newDirectChat();\n  chat.model = dom.modelSelect.value || chat.model;\n  chat.workspace = dom.dirInput.value.trim() || chat.workspace;\n  if (!chat.items.length) chat.title = text.slice(0, 40) || \"محادثة جديدة\";\n  chat.updated = Date.now();\n  chat.items.push({ kind: \"user\", text });\n  saveDirectChats();\n\n  dom.input.value = \"\";\n  autoGrow();\n  state.running = true;\n  updateRunningUi();\n  renderMessages();\n  renderDirectList();\n  scrollToBottom(true);\n\n  let item = null;\n  const ensureItem = () => {\n    if (!item) {\n      item = { kind: \"assistant\", text: \"\", reasoning: \"\", tools: [], usage: null, model: chat.model };\n      chat.items.push(item);\n    }\n    return item;\n  };\n\n  try {\n    directAbort = new AbortController();\n    const res = await fetch(\"/api/direct/chat\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ model: chat.model, messages: directHistory(chat), workspace: chat.workspace || undefined }),\n      signal: directAbort.signal,\n    });\n\n    if (res.status === 401) {\n      showLogin();\n      throw new Error(\"خاصك تسجل الدخول\");\n    }\n    if (!res.ok || !res.body) {\n      const raw = await res.text().catch(() => \"\");\n      let msg = raw;\n      try {\n        msg = JSON.parse(raw).error || raw;\n      } catch {\n        /* نص */\n      }\n      throw new Error(msg || `HTTP ${res.status}`);\n    }\n\n    const reader = res.body.getReader();\n    const dec = new TextDecoder();\n    let buf = \"\";\n\n    for (;;) {\n      const { value, done } = await reader.read();\n      if (done) break;\n      buf += dec.decode(value, { stream: true });\n      let i;\n      while ((i = buf.indexOf(\"\\n\\n\")) >= 0) {\n        const raw = buf.slice(0, i);\n        buf = buf.slice(i + 2);\n        if (!raw.startsWith(\"data:\")) continue;\n        let ev;\n        try {\n          ev = JSON.parse(raw.slice(5).trim());\n        } catch {\n          continue;\n        }\n        if (ev.type === \"step.start\") item = null;\n        else if (ev.type === \"text.delta\") {\n          ensureItem().text += ev.delta;\n          queueRender();\n        } else if (ev.type === \"reasoning.delta\") {\n          ensureItem().reasoning += ev.delta;\n          queueRender();\n        } else if (ev.type === \"tool.start\") {\n          ensureItem().tools.push({ id: ev.id, name: ev.name, input: ev.input, status: \"running\", output: \"\" });\n          queueRender();\n        } else if (ev.type === \"tool.end\") {\n          const cur = ensureItem().tools.find((t) => t.id === ev.id);\n          if (cur) {\n            cur.status = ev.status;\n            cur.output = ev.output || \"\";\n            cur.error = ev.error || null;\n          }\n          queueRender();\n        } else if (ev.type === \"step.end\") {\n          ensureItem().usage = ev.usage;\n          if (ev.model) ensureItem().model = ev.model;\n          queueRender();\n        } else if (ev.type === \"error\") {\n          chat.items.push({ kind: \"assistant\", text: \"\", tools: [], error: ev.message || \"خطأ غير معروف\" });\n          queueRender();\n        }\n      }\n    }\n  } catch (err) {\n    if (err.name !== \"AbortError\") {\n      const c = currentChat();\n      c.items.push({ kind: \"assistant\", text: \"\", tools: [], error: err.message });\n    }\n  } finally {\n    state.running = false;\n    updateRunningUi();\n    const c = currentChat();\n    if (c) c.updated = Date.now();\n    saveDirectChats();\n    renderMessages();\n    renderDirectList();\n  }\n}\n\nasync function regenerate() {\n  if (!isDirect() || state.running) return;\n  const chat = currentChat();\n  if (!chat) return;\n  let idx = -1;\n  for (let i = chat.items.length - 1; i >= 0; i--) {\n    if (chat.items[i].kind === \"user\") {\n      idx = i;\n      break;\n    }\n  }\n  if (idx < 0) return;\n  const text = chat.items[idx].text;\n  chat.items = chat.items.slice(0, idx); // حيّد الرسالة القديمة وكل اللي بعدها\n  saveDirectChats();\n  renderMessages();\n  await sendDirect(text);\n}\n\nasync function stopRun() {\n  if (isDirect()) {\n    if (directAbort) directAbort.abort();\n    state.running = false;\n    updateRunningUi();\n    return;\n  }\n  if (!state.session) return;\n  try {\n    await api(`/api/sessions/${encodeURIComponent(state.session.id)}/interrupt`, { method: \"POST\" });\n    state.running = false;\n    updateRunningUi();\n    scheduleRefresh(300);\n  } catch (err) {\n    toast(\"تعذّر الإيقاف: \" + err.message);\n  }\n}\n\n/* ------------------------------------------------------------------ الوضعان */\n\nfunction setMode(mode) {\n  state.mode = mode;\n  localStorage.setItem(LS.mode, mode);\n  dom.modeLocal.classList.toggle(\"on\", mode === \"local\");\n  dom.modeDirect.classList.toggle(\"on\", mode === \"direct\");\n\n  // الوضع المحلي مسدود على سيرفر عمومي (نفق / نشر)\n  const localOk = state.localAvailable !== false;\n  dom.modeLocal.disabled = !localOk;\n  dom.modeLocal.title = localOk ? \"\" : \"الوضع المحلي مسدود فهاد السيرفر (كيوصل لملفات الحاسوب)\";\n\n  state.session = null;\n  state.messages = [];\n  state.deltas.clear();\n  state.usage = null;\n  state.permissions = [];\n  state.running = false;\n\n  if (mode === \"direct\") {\n    loadDirectChats();\n    if (!state.direct.current && state.direct.chats[0]) state.direct.current = state.direct.chats[0];\n  }\n\n  renderFieldVisibility();\n  updateRunningUi();\n  renderMessages();\n  refreshSidebar();\n  loadModels();\n  if (mode === \"direct\") loadDirectStatus();\n  else loadHealth();\n}\n\nfunction refreshSidebar() {\n  if (isDirect()) renderDirectList();\n  else loadSessions();\n}\n\n/* ------------------------------------------------------------------ التهيئة */\n\nfunction bind() {\n  const ids = {\n    btnMenu: \"#btn-menu\", btnModel: \"#btn-model\", chipModel: \"#chip-model\", btnTheme: \"#btn-theme\",\n    themeIcon: \"#theme-icon\", viewWelcome: \"#view-welcome\", viewChat: \"#view-chat\",\n    chips: \"#chips\", wsBadge: \"#ws-badge\", wsDetail: \"#ws-detail\", messages: \"#messages\",\n    permissions: \"#permissions\", btnPlus: \"#btn-plus\", input: \"#input\",\n    btnMic: \"#btn-mic\", btnSend: \"#btn-send\", btnStop: \"#btn-stop\", scrim: \"#scrim\",\n    drawer: \"#drawer\", btnDrawerClose: \"#btn-drawer-close\", btnNew: \"#btn-new\", btnSearch: \"#btn-search\",\n    btnInstall: \"#btn-install\",\n    sessionSearch: \"#session-search\", sessionList: \"#session-list\", btnRefresh: \"#btn-refresh\",\n    btnSettings: \"#btn-settings\", statusPill: \"#status-pill\", statusDetail: \"#status-detail\",\n    settings: \"#settings\", btnSettingsBack: \"#btn-settings-back\", modeLocal: \"#mode-local\",\n    modeDirect: \"#mode-direct\", modelSelect: \"#model-select\", showAll: \"#show-all\",\n    models: \"#models\", btnModels: \"#btn-models\", btnModelsBack: \"#btn-models-back\",\n    btnModelsRefresh: \"#btn-models-refresh\", modelSearch: \"#model-search\", modelCount: \"#model-count\",\n    modelList: \"#model-list\", modelFilters: \"#model-filters\", btnPickModel: \"#btn-pick-model\",\n    pickModelName: \"#pick-model-name\",\n    agentField: \"#agent-field\", agentSelect: \"#agent-select\", dirField: \"#dir-field\",\n    dirInput: \"#dir-input\", gatewayUrl: \"#gateway-url\", directNote: \"#direct-note\", btnSave: \"#btn-save\",\n    btnDelete: \"#btn-delete\", login: \"#login\", loginForm: \"#login-form\", loginPassword: \"#login-password\",\n    loginError: \"#login-error\", toast: \"#toast\",\n  };\n  for (const [k, sel] of Object.entries(ids)) dom[k] = $(sel);\n\n  dom.showAll.checked = localStorage.getItem(LS.showAll) === \"1\";\n  try {\n    state.favs = new Set(JSON.parse(localStorage.getItem(LS.favs) || \"[]\"));\n  } catch {\n    state.favs = new Set();\n  }\n  applyTheme(state.theme, false);\n\n  // الشريط العلوي\n  dom.btnMenu.addEventListener(\"click\", openDrawer);\n  dom.btnModel.addEventListener(\"click\", openModels);\n  dom.btnTheme.addEventListener(\"click\", () => {\n    const order = [\"system\", \"light\", \"dark\"];\n    const next = order[(order.indexOf(state.theme) + 1) % order.length];\n    applyTheme(next);\n    toast(\"المظهر: \" + (next === \"system\" ? \"حسب النظام\" : next === \"light\" ? \"فاتح\" : \"غامق\"));\n  });\n\n  // الترحيب\n  dom.chips.addEventListener(\"click\", (e) => {\n    const chip = e.target.closest(\".chip\");\n    if (!chip) return;\n    dom.input.value = chip.dataset.prompt || \"\";\n    autoGrow();\n    sendMessage();\n  });\n\n  // القائمة\n  dom.btnDrawerClose.addEventListener(\"click\", closeDrawer);\n  dom.scrim.addEventListener(\"click\", closeDrawer);\n  dom.btnNew.addEventListener(\"click\", newChat);\n  dom.btnSearch.addEventListener(\"click\", () => {\n    dom.sessionSearch.classList.toggle(\"hidden\");\n    if (!dom.sessionSearch.classList.contains(\"hidden\")) dom.sessionSearch.focus();\n  });\n  dom.btnSettings.addEventListener(\"click\", openSettings);\n  dom.btnRefresh.addEventListener(\"click\", async () => {\n    if (isDirect()) await loadDirectStatus();\n    else await loadHealth();\n    await loadModels();\n    refreshSidebar();\n    if (!isDirect() && state.session) await openSession(state.session.id);\n    toast(\"تحدّث\");\n  });\n\n  let searchTimer = null;\n  dom.sessionSearch.addEventListener(\"input\", () => {\n    clearTimeout(searchTimer);\n    searchTimer = setTimeout(refreshSidebar, 180);\n  });\n\n  // الإعدادات\n  dom.btnSettingsBack.addEventListener(\"click\", closeSettings);\n  dom.btnSave.addEventListener(\"click\", () => {\n    closeSettings();\n    toast(\"تسجّل\");\n  });\n  dom.modeLocal.addEventListener(\"click\", () => setMode(\"local\"));\n  dom.modeDirect.addEventListener(\"click\", () => setMode(\"direct\"));\n  $$(\".preset[data-theme]\").forEach((b) =>\n    b.addEventListener(\"click\", () => applyTheme(b.dataset.theme))\n  );\n\n  dom.modelSelect.addEventListener(\"change\", applyModelChange);\n\n  // شاشة اختيار النموذج\n  dom.btnModels.addEventListener(\"click\", openModels);\n  dom.btnModelsBack.addEventListener(\"click\", closeModels);\n  dom.btnPickModel.addEventListener(\"click\", openModels);\n  dom.btnModelsRefresh.addEventListener(\"click\", async () => {\n    await loadModels();\n    toast(\"تحدّثت قائمة النماذج\");\n  });\n  let modelSearchTimer = null;\n  dom.modelSearch.addEventListener(\"input\", () => {\n    clearTimeout(modelSearchTimer);\n    modelSearchTimer = setTimeout(renderModelList, 140);\n  });\n  dom.modelFilters.addEventListener(\"click\", (e) => {\n    const b = e.target.closest(\"[data-filter]\");\n    if (!b) return;\n    state.modelFilter = b.dataset.filter;\n    $$(\"#model-filters .preset\").forEach((x) => x.classList.toggle(\"on\", x === b));\n    renderModelList();\n  });\n\n  dom.agentSelect.addEventListener(\"change\", () => localStorage.setItem(LS.agent, dom.agentSelect.value));\n  dom.showAll.addEventListener(\"change\", () => {\n    localStorage.setItem(LS.showAll, dom.showAll.checked ? \"1\" : \"0\");\n    renderModelSelect();\n  });\n  dom.dirInput.addEventListener(\"change\", () => {\n    localStorage.setItem(LS.dir, dom.dirInput.value.trim());\n    if (isDirect()) {\n      const chat = currentChat();\n      if (chat) {\n        chat.workspace = dom.dirInput.value.trim();\n        saveDirectChats();\n      }\n      return;\n    }\n    loadModels();\n  });\n\n  dom.btnDelete.addEventListener(\"click\", async () => {\n    if (isDirect()) {\n      const chat = currentChat();\n      if (!chat) return toast(\"ما كاينة محادثة\");\n      if (!confirm(\"حذف هذه المحادثة؟\")) return;\n      state.direct.chats = state.direct.chats.filter((c) => c.id !== chat.id);\n      state.direct.current = null;\n      saveDirectChats();\n      closeSettings();\n      renderMessages();\n      renderDirectList();\n      toast(\"تحذفات المحادثة\");\n      return;\n    }\n    if (!state.session) return toast(\"ما كاينة محادثة\");\n    if (!confirm(\"حذف هذه المحادثة؟\")) return;\n    await api(`/api/sessions/${encodeURIComponent(state.session.id)}`, { method: \"DELETE\" });\n    closeSettings();\n    newChat();\n    toast(\"تحذفات المحادثة\");\n  });\n\n  // الإدخال\n  dom.btnSend.addEventListener(\"click\", sendMessage);\n  dom.btnStop.addEventListener(\"click\", stopRun);\n  dom.btnPlus.addEventListener(\"click\", openSettings);\n  dom.input.addEventListener(\"keydown\", (e) => {\n    if (e.key === \"Enter\" && !e.shiftKey) {\n      e.preventDefault();\n      sendMessage();\n    }\n  });\n  dom.input.addEventListener(\"input\", autoGrow);\n\n  // الإدخال الصوتي (إن توفّر)\n  dom.btnMic.addEventListener(\"click\", () => {\n    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;\n    if (!SR) return toast(\"الإدخال الصوتي غير مدعوم فهاد المتصفح\");\n    if (recognizer) {\n      recognizer.stop();\n      recognizer = null;\n      return;\n    }\n    recognizer = new SR();\n    recognizer.lang = \"ar-SA\";\n    recognizer.continuous = false;\n    recognizer.interimResults = true;\n    recognizer.onresult = (e) => {\n      let text = \"\";\n      for (const r of e.results) text += r[0].transcript;\n      dom.input.value = text;\n      autoGrow();\n    };\n    recognizer.onend = () => {\n      recognizer = null;\n    };\n    recognizer.onerror = () => {\n      recognizer = null;\n      toast(\"تعذّر الإدخال الصوتي\");\n    };\n    try {\n      recognizer.start();\n    } catch {\n      recognizer = null;\n    }\n  });\n\n  // تسجيل الدخول\n  dom.loginForm.addEventListener(\"submit\", async (e) => {\n    e.preventDefault();\n    dom.loginError.classList.add(\"hidden\");\n    try {\n      const res = await fetch(\"/api/login\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ password: dom.loginPassword.value }),\n      });\n      const data = await res.json().catch(() => ({}));\n      if (!res.ok) throw new Error(data.error || \"كلمة السر غير صحيحة\");\n      dom.login.classList.add(\"hidden\");\n      dom.loginPassword.value = \"\";\n      await initData();\n    } catch (err) {\n      dom.loginError.textContent = err.message;\n      dom.loginError.classList.remove(\"hidden\");\n    }\n  });\n\n  // تغيّر مظهر النظام\n  window.matchMedia(\"(prefers-color-scheme: light)\").addEventListener(\"change\", () => {\n    if (state.theme === \"system\") applyTheme(\"system\", false);\n  });\n\n  window.addEventListener(\"keydown\", (e) => {\n    if (e.key === \"Escape\") {\n      closeModels();\n      closeSettings();\n      closeDrawer();\n    }\n  });\n}\n\nasync function initData() {\n  if (!isDirect()) await loadHealth();\n  await loadModels();\n  await loadAgents();\n  if (isDirect()) {\n    loadDirectChats();\n    if (!state.direct.current && state.direct.chats[0]) state.direct.current = state.direct.chats[0];\n    renderDirectList();\n    await loadDirectStatus();\n  } else {\n    await loadSessions();\n  }\n  updateHeader();\n  renderMessages();\n  updateRunningUi();\n}\n\nasync function init() {\n  bind();\n  setupPwa();\n  // إلا كان الوضع المحلي مسدود على هاد السيرفر (نفق ولا نشر) → دوز مباشرة للوضع المباشر\n  if (state.mode === \"local\") {\n    try {\n      const h = await api(\"/api/health\");\n      state.localAvailable = h.localAvailable !== false;\n      if (!state.localAvailable) {\n        state.mode = \"direct\";\n        localStorage.setItem(LS.mode, \"direct\");\n        setTimeout(() => toast(\"الوضع المحلي مسدود فهاد السيرفر — دوزنا للوضع «مباشر»\"), 1000);\n      }\n    } catch {\n      /* تجاهل */\n    }\n  }\n  setMode(state.mode);\n  renderMessages();\n  updateRunningUi();\n  await initData();\n  connectEvents();\n  startPolling();\n  autoGrow();\n  dom.input.focus();\n}\n\ninit();\n","apple-touch-icon.png":{"__b64":""},"icon-192.png":{"__b64":""},"icon-512.png":{"__b64":""},"icon-maskable-512.png":{"__b64":""},"index.html":"<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\" data-theme=\"dark\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n<meta name=\"theme-color\" content=\"#0c0d12\" />\n<title>Rtl AI — نماذج مجانية</title>\n<link rel=\"manifest\" href=\"/manifest.webmanifest\" />\n<link rel=\"icon\" href=\"/icon-192.png\" sizes=\"192x192\" type=\"image/png\" />\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\" />\n<meta name=\"mobile-web-app-capable\" content=\"yes\" />\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\" />\n<meta name=\"apple-mobile-web-app-title\" content=\"Rtl AI\" />\n<meta name=\"description\" content=\"محادثة مع نماذج OpenCode المجانية — بالعربية، بلا تسجيل دخول.\" />\n<link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n\n<div class=\"stage\">\n  <div class=\"app\">\n\n    <!-- ================= الشريط العلوي ================= -->\n    <header class=\"topbar\">\n      <button id=\"btn-menu\" class=\"iconbtn\" title=\"القائمة\" aria-label=\"القائمة\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M3 6h18M3 12h18M3 18h18\"/></svg>\n      </button>\n\n      <button id=\"btn-model\" class=\"modelchip\" title=\"تغيير النموذج\">\n        <span id=\"chip-model\">…</span>\n        <svg viewBox=\"0 0 24 24\"><path d=\"M6 9l6 6 6-6\"/></svg>\n      </button>\n\n      <div class=\"spacer\"></div>\n\n      <button id=\"btn-theme\" class=\"iconbtn\" title=\"تبديل المظهر\" aria-label=\"تبديل المظهر\">\n        <svg viewBox=\"0 0 24 24\" id=\"theme-icon\"><path d=\"M21 12.8A9 9 0 1111.2 3a7 7 0 009.8 9.8z\"/></svg>\n      </button>\n\n      <div class=\"avatar\">ر</div>\n    </header>\n\n    <!-- ================= شاشة الترحيب ================= -->\n    <main id=\"view-welcome\" class=\"view welcome\">\n      <div class=\"hello\"><span class=\"g\" id=\"hello-name\">أهلاً بك</span></div>\n      <div class=\"sub\" id=\"hello-sub\">كيفاش نقدر نعاونك اليوم؟</div>\n\n      <div class=\"chips\" id=\"chips\">\n        <button class=\"chip\" data-prompt=\"اشرح لي كيفاش كيخدم الذكاء الاصطناعي ببساطة، بمثال من الحياة اليومية.\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M12 3l1.6 5.4L19 10l-5.4 1.6L12 17l-1.6-5.4L5 10l5.4-1.6z\"/></svg>\n          <span>اشرح لي الذكاء الاصطناعي ببساطة</span>\n        </button>\n        <button class=\"chip\" data-prompt=\"كتب لي رسالة تقديم (cover letter) قصيرة واحترافية لمنصب مطوّر برمجيات.\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M4 19V5a2 2 0 012-2h9l5 5v11a2 2 0 01-2 2H6a2 2 0 01-2-2z\"/><path d=\"M8 13h8M8 17h5\"/></svg>\n          <span>كتب لي رسالة تقديم للعمل</span>\n        </button>\n        <button class=\"chip\" data-prompt=\"دير لي خطة مراجعة منظمة للامتحانات على مدى أسبوعين.\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M8 3v4M16 3v4M4 9h16M5 5h14a1 1 0 011 1v13a1 1 0 01-1 1H5a1 1 0 01-1-1V6a1 1 0 011-1z\"/></svg>\n          <span>خطة مراجعة للامتحانات</span>\n        </button>\n        <button class=\"chip\" data-prompt=\"ترجم هاد النص للعربية بأسلوب طبيعي وسلس: &quot;Small steps every day lead to big results.&quot;\">\n          <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c3 3.5 3 14.5 0 18\"/></svg>\n          <span>ترجم نص للعربية</span>\n        </button>\n      </div>\n\n      <div class=\"wsline\">\n        <span id=\"ws-badge\" class=\"pill\">…</span>\n        <span id=\"ws-detail\" class=\"muted\"></span>\n      </div>\n    </main>\n\n    <!-- ================= شاشة المحادثة ================= -->\n    <main id=\"view-chat\" class=\"view chat hidden\">\n      <div id=\"messages\" class=\"messages\"></div>\n    </main>\n\n    <!-- ================= الأذونات (الوضع المحلي) ================= -->\n    <div id=\"permissions\" class=\"permissions hidden\"></div>\n\n    <!-- ================= شريط الإدخال ================= -->\n    <div class=\"inputwrap\">\n      <div class=\"inputbar\">\n        <button class=\"roundbtn\" id=\"btn-plus\" title=\"مجلد العمل / الإعدادات\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></svg>\n        </button>\n        <textarea id=\"input\" rows=\"1\" placeholder=\"اكتب رسالتك…\" autocomplete=\"off\"></textarea>\n        <button class=\"roundbtn\" id=\"btn-mic\" title=\"إدخال صوتي (المتصفح)\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M12 14a3 3 0 003-3V6a3 3 0 10-6 0v5a3 3 0 003 3z\"/><path d=\"M5 11a7 7 0 0014 0M12 18v3\"/></svg>\n        </button>\n        <button class=\"roundbtn sendbtn\" id=\"btn-send\" title=\"إرسال\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M4 20l16-8L4 4v6l10 2-10 2z\"/></svg>\n        </button>\n        <button class=\"roundbtn stopbtn hidden\" id=\"btn-stop\" title=\"إيقاف\">\n          <svg viewBox=\"0 0 24 24\"><rect x=\"6\" y=\"6\" width=\"12\" height=\"12\" rx=\"2.5\"/></svg>\n        </button>\n      </div>\n      <div class=\"disclaimer\" id=\"disclaimer\">النماذج المجانية يمكن تعطي معلومات غير دقيقة — تحقق منها.</div>\n    </div>\n\n  </div>\n</div>\n\n<!-- ================= القائمة الجانبية ================= -->\n<div id=\"scrim\" class=\"scrim hidden\"></div>\n<aside id=\"drawer\" class=\"drawer\" aria-hidden=\"true\">\n  <div class=\"dhead\">\n    <div class=\"logo\"><svg viewBox=\"0 0 24 24\"><path fill=\"#fff\" d=\"M12 2l1.9 7.1L21 11l-7.1 1.9L12 20l-1.9-7.1L3 11l7.1-1.9z\"/></svg></div>\n    <span>Rtl <b>AI</b></span>\n    <button id=\"btn-drawer-close\" class=\"iconbtn small\" title=\"إغلاق\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n    </button>\n  </div>\n\n  <button class=\"ditem\" id=\"btn-new\">\n    <svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></svg> محادثة جديدة\n  </button>\n  <button class=\"ditem\" id=\"btn-models\">\n    <svg viewBox=\"0 0 24 24\"><path d=\"M12 3l1.6 5.4L19 10l-5.4 1.6L12 17l-1.6-5.4L5 10l5.4-1.6z\"/></svg> اختيار النموذج\n  </button>\n  <button class=\"ditem hidden\" id=\"btn-install\">\n    <svg viewBox=\"0 0 24 24\"><path d=\"M12 3v12M7 11l5 5 5-5M4 21h16\"/></svg> ثبّت التطبيق\n  </button>\n  <button class=\"ditem\" id=\"btn-search\">\n    <svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M20 20l-3.5-3.5\"/></svg> بحث في المحادثات\n  </button>\n  <input id=\"session-search\" class=\"dsearch hidden\" type=\"search\" placeholder=\"بحث…\" />\n\n  <div class=\"dsection\">الأخيرة</div>\n  <div id=\"session-list\" class=\"dlist\"></div>\n\n  <div class=\"spacer\"></div>\n\n  <button class=\"ditem\" id=\"btn-refresh\">\n    <svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 11-3-6.7M21 4v5h-5\"/></svg> تحديث\n  </button>\n  <button class=\"ditem\" id=\"btn-settings\">\n    <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.7 1.7 0 00.3 1.9l.1.1a2 2 0 11-2.8 2.8l-.1-.1a1.7 1.7 0 00-2.9 1.2 2 2 0 11-4 0 1.7 1.7 0 00-2.9-1.2l-.1.1a2 2 0 11-2.8-2.8l.1-.1A1.7 1.7 0 003 15a2 2 0 010-4 1.7 1.7 0 001.2-2.9l-.1-.1a2 2 0 112.8-2.8l.1.1A1.7 1.7 0 0010 4.6a2 2 0 014 0 1.7 1.7 0 002.9 1.2l.1-.1a2 2 0 112.8 2.8l-.1.1A1.7 1.7 0 0021 11a2 2 0 010 4z\"/></svg> الإعدادات\n  </button>\n  <div class=\"dfooter\">\n    <span id=\"status-pill\" class=\"pill\">…</span>\n    <span id=\"status-detail\" class=\"muted\"></span>\n  </div>\n</aside>\n\n<!-- ================= اختيار النموذج ================= -->\n<div id=\"models\" class=\"sheet\">\n  <div class=\"sheet-head\">\n    <button id=\"btn-models-back\" class=\"iconbtn\" title=\"رجوع\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M20 12H4M10 6l-6 6 6 6\"/></svg>\n    </button>\n    <h2>اختيار النموذج</h2>\n    <span class=\"spacer\"></span>\n    <button id=\"btn-models-refresh\" class=\"iconbtn\" title=\"تحديث القائمة\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 11-3-6.7M21 4v5h-5\"/></svg>\n    </button>\n  </div>\n\n  <div class=\"sheet-body\">\n    <div class=\"field\">\n      <input id=\"model-search\" type=\"search\" placeholder=\"بحث… (مثال: deepseek)\" autocomplete=\"off\" />\n    </div>\n\n    <div class=\"presets\" id=\"model-filters\">\n      <button class=\"preset on\" data-filter=\"free\">مجاني</button>\n      <button class=\"preset\" data-filter=\"all\">الكل</button>\n      <button class=\"preset\" data-filter=\"fav\">★ المفضلة</button>\n    </div>\n\n    <div id=\"model-count\" class=\"mcount muted\"></div>\n    <div id=\"model-list\" class=\"mlist\"></div>\n  </div>\n</div>\n\n<!-- ================= الإعدادات ================= -->\n<div id=\"settings\" class=\"sheet hidden\">\n  <div class=\"sheet-head\">\n    <button id=\"btn-settings-back\" class=\"iconbtn\" title=\"رجوع\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M20 12H4M10 6l-6 6 6 6\"/></svg>\n    </button>\n    <h2>الإعدادات</h2>\n  </div>\n\n  <div class=\"sheet-body\">\n    <div class=\"label\">الوضع</div>\n    <div class=\"presets\">\n      <button class=\"preset\" id=\"mode-local\">عبر opencode</button>\n      <button class=\"preset\" id=\"mode-direct\">مباشر</button>\n    </div>\n\n    <div class=\"field\">\n      <div class=\"label\">النموذج</div>\n      <button class=\"input pickerbtn\" id=\"btn-pick-model\" type=\"button\">\n        <span id=\"pick-model-name\">…</span>\n        <svg viewBox=\"0 0 24 24\"><path d=\"M6 9l6 6 6-6\"/></svg>\n      </button>\n      <label class=\"check\">\n        <input id=\"show-all\" type=\"checkbox\" />\n        <span>إظهار النماذج اللي كتحتاج مفتاح</span>\n      </label>\n    </div>\n    <select id=\"model-select\" class=\"hidden\" aria-hidden=\"true\" tabindex=\"-1\"></select>\n\n    <div class=\"field\" id=\"agent-field\">\n      <div class=\"label\">الوكيل</div>\n      <select id=\"agent-select\"></select>\n    </div>\n\n    <div class=\"field\" id=\"dir-field\">\n      <div class=\"label\">مجلد العمل</div>\n      <input id=\"dir-input\" type=\"text\" spellcheck=\"false\" placeholder=\"C:\\Users\\...\" />\n    </div>\n\n    <div class=\"field\">\n      <div class=\"label\">المظهر</div>\n      <div class=\"presets\">\n        <button class=\"preset\" data-theme=\"system\">النظام</button>\n        <button class=\"preset\" data-theme=\"light\">فاتح</button>\n        <button class=\"preset\" data-theme=\"dark\">غامق</button>\n      </div>\n    </div>\n\n    <div class=\"field\">\n      <div class=\"label\">البوابة (للوضع المباشر)</div>\n      <div class=\"input mono\" id=\"gateway-url\">https://opencode.ai/inference/v1</div>\n    </div>\n\n    <div id=\"direct-note\" class=\"note hidden\">…</div>\n\n    <button class=\"savebtn\" id=\"btn-save\">حفظ ورجوع</button>\n    <button class=\"linkbtn\" id=\"btn-delete\">🗑 حذف المحادثة الحالية</button>\n  </div>\n</div>\n\n<!-- ================= تسجيل الدخول ================= -->\n<div id=\"login\" class=\"login hidden\">\n  <form id=\"login-form\" class=\"login-card\">\n    <div class=\"logo big\"><svg viewBox=\"0 0 24 24\"><path fill=\"#fff\" d=\"M12 2l1.9 7.1L21 11l-7.1 1.9L12 20l-1.9-7.1L3 11l7.1-1.9z\"/></svg></div>\n    <h2>هاد الموقع محمي</h2>\n    <p class=\"muted\">اكتب كلمة السر باش تكمّل.</p>\n    <input id=\"login-password\" type=\"password\" placeholder=\"كلمة السر\" autocomplete=\"current-password\" />\n    <button class=\"savebtn\" type=\"submit\">دخول</button>\n    <div id=\"login-error\" class=\"note error hidden\"></div>\n  </form>\n</div>\n\n<div id=\"toast\" class=\"toast hidden\"></div>\n\n<script src=\"/app.js\"></script>\n</body>\n</html>\n","manifest.webmanifest":"{\n  \"name\": \"Rtl AI — نماذج مجانية\",\n  \"short_name\": \"Rtl AI\",\n  \"description\": \"محادثة بالعربية مع نماذج OpenCode المجانية — بلا تسجيل دخول.\",\n  \"lang\": \"ar\",\n  \"dir\": \"rtl\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"id\": \"/\",\n  \"display\": \"standalone\",\n  \"display_override\": [\"standalone\", \"minimal-ui\", \"browser\"],\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#0c0d12\",\n  \"theme_color\": \"#0c0d12\",\n  \"categories\": [\"productivity\", \"utilities\"],\n  \"icons\": [\n    { \"src\": \"/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/icon-maskable-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\" }\n  ],\n  \"shortcuts\": [\n    {\n      \"name\": \"محادثة جديدة\",\n      \"short_name\": \"جديدة\",\n      \"url\": \"/?new=1\",\n      \"icons\": [{ \"src\": \"/icon-192.png\", \"sizes\": \"192x192\" }]\n    }\n  ]\n}\n","style.css":"/* ====================== Rtl AI — واجهة على نمط تطبيق موبايل ====================== */\n\n:root {\n  --grad: linear-gradient(90deg, #4285F4 0%, #9B72CB 55%, #D96570 100%);\n  --grad2: linear-gradient(135deg, #4285F4, #9B72CB, #D96570);\n  --font: \"Segoe UI\", Roboto, -apple-system, \"Helvetica Neue\", Arial, \"Noto Naskh Arabic\", \"Tahoma\", sans-serif;\n  --mono: \"Cascadia Code\", Consolas, \"Courier New\", monospace;\n  --radius: 20px;\n}\n\nhtml[data-theme=\"dark\"] {\n  --bg: #1b1b1f;\n  --bg-stage: radial-gradient(1200px 700px at 20% -10%, #1d2233 0%, #0c0d12 55%, #07080b 100%);\n  --surface: #282a2c;\n  --surface2: #333537;\n  --text: #e3e3e3;\n  --muted: #9aa0a6;\n  --line: #2f3033;\n  --accent: #a8c7fa;\n  --accent-ink: #062e6f;\n  --code: #0f1013;\n  --code-ink: #8ab4f8;\n  --shadow: 0 30px 70px rgba(0, 0, 0, .65);\n  --danger: #f28b82;\n}\n\nhtml[data-theme=\"light\"] {\n  --bg: #ffffff;\n  --bg-stage: radial-gradient(1200px 700px at 20% -10%, #eef3fb 0%, #f6f8fb 55%, #e9edf3 100%);\n  --surface: #f0f4f9;\n  --surface2: #e9eef6;\n  --text: #1f1f1f;\n  --muted: #5f6368;\n  --line: #e1e3e1;\n  --accent: #0b57d0;\n  --accent-ink: #ffffff;\n  --code: #f1f3f4;\n  --code-ink: #1a73e8;\n  --shadow: 0 24px 60px rgba(60, 64, 67, .22);\n  --danger: #b3261e;\n}\n\n* { box-sizing: border-box; margin: 0; padding: 0; }\n\nhtml, body { height: 100%; }\n\nbody {\n  font-family: var(--font);\n  background: var(--bg-stage);\n  color: var(--text);\n  overflow: hidden;\n  -webkit-font-smoothing: antialiased;\n}\n\n.hidden { display: none !important; }\n.muted { color: var(--muted); font-size: 12px; }\n.spacer { flex: 1; }\n\n/* ---------------- الإطار ---------------- */\n\n.stage { height: 100dvh; display: flex; justify-content: center; }\n\n.app {\n  width: 100%;\n  max-width: 780px;\n  height: 100dvh;\n  display: flex;\n  flex-direction: column;\n  background: var(--bg);\n  position: relative;\n  overflow: hidden;\n}\n\n@media (min-width: 860px) {\n  .stage { align-items: center; padding: 18px; }\n  .app {\n    height: calc(100dvh - 36px);\n    border-radius: 26px;\n    box-shadow: var(--shadow), 0 0 0 1px rgba(255, 255, 255, .07) inset;\n  }\n}\n\n/* ---------------- الشريط العلوي ---------------- */\n\n.topbar {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 10px 12px 6px;\n  flex: 0 0 auto;\n}\n\n.iconbtn {\n  width: 40px;\n  height: 40px;\n  border: 0;\n  border-radius: 50%;\n  background: transparent;\n  color: inherit;\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n  flex: 0 0 auto;\n  transition: background .15s;\n}\n\n.iconbtn:hover { background: var(--surface); }\n.iconbtn.small { width: 32px; height: 32px; }\n\n.iconbtn svg,\n.ditem svg,\n.roundbtn svg,\n.chip svg,\n.actions svg,\n.modelchip svg,\n.preset svg {\n  width: 20px;\n  height: 20px;\n  stroke: currentColor;\n  fill: none;\n  stroke-width: 1.9;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.iconbtn.small svg { width: 17px; height: 17px; }\n\n.modelchip {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  padding: 9px 14px;\n  border: 0;\n  border-radius: 20px;\n  background: var(--surface);\n  color: var(--text);\n  font: inherit;\n  font-size: 13.5px;\n  font-weight: 500;\n  white-space: nowrap;\n  cursor: pointer;\n  max-width: 58vw;\n  overflow: hidden;\n}\n\n.modelchip svg { width: 15px; height: 15px; stroke-width: 2.2; flex: 0 0 auto; }\n#chip-model { overflow: hidden; text-overflow: ellipsis; }\n\n.avatar {\n  width: 34px;\n  height: 34px;\n  border-radius: 50%;\n  background: var(--grad2);\n  display: grid;\n  place-items: center;\n  color: #fff;\n  font-size: 13px;\n  font-weight: 700;\n  flex: 0 0 auto;\n}\n\n/* ---------------- الشاشات ---------------- */\n\n.view { flex: 1; min-height: 0; display: flex; flex-direction: column; }\n\n/* ---------------- الترحيب ---------------- */\n\n.welcome {\n  justify-content: center;\n  padding: 0 22px;\n  gap: 24px;\n}\n\n.hello {\n  font-size: clamp(26px, 7.5vw, 34px);\n  font-weight: 600;\n  line-height: 1.2;\n  letter-spacing: -.4px;\n}\n\n.hello .g {\n  background: var(--grad);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n\n.sub { font-size: 13.5px; color: var(--muted); margin-top: 10px; }\n\n.chips { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n\n.chip {\n  border: 0;\n  text-align: start;\n  border-radius: 16px;\n  padding: 14px 13px;\n  font: inherit;\n  font-size: 12.5px;\n  line-height: 1.4;\n  min-height: 86px;\n  background: var(--surface);\n  color: var(--text);\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  gap: 9px;\n  cursor: pointer;\n  transition: transform .15s, background .15s;\n}\n\n.chip:hover { background: var(--surface2); transform: translateY(-2px); }\n.chip svg { stroke: #4285F4; }\n\n.wsline { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n\n/* ---------------- المحادثة ---------------- */\n\n.chat { padding: 0; }\n\n.messages {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 12px 18px 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 22px;\n  scroll-behavior: smooth;\n}\n\n.messages::-webkit-scrollbar { width: 8px; }\n.messages::-webkit-scrollbar-thumb { background: var(--line); border-radius: 8px; }\n\n.userrow { display: flex; justify-content: flex-end; }\n\n.bubble {\n  max-width: 84%;\n  padding: 11px 15px;\n  border-radius: 20px 20px 4px 20px;\n  font-size: 13.5px;\n  line-height: 1.6;\n  background: var(--surface2);\n  color: var(--text);\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.airow { display: flex; gap: 11px; align-items: flex-start; }\n\n.aispark { width: 28px; height: 28px; flex: 0 0 auto; margin-top: 2px; }\n.aispark svg { width: 28px; height: 28px; }\n\n.aicontent { flex: 1; min-width: 0; }\n\n.role {\n  font-size: 11px;\n  color: var(--muted);\n  margin-bottom: 5px;\n  letter-spacing: .2px;\n}\n\n.aitext,\n.md {\n  font-size: 13.8px;\n  line-height: 1.7;\n  color: var(--text);\n  word-break: break-word;\n}\n\n.md p { margin: 0 0 10px; }\n.md p:last-child { margin-bottom: 0; }\n.md strong { font-weight: 700; }\n.md code {\n  font-family: var(--mono);\n  font-size: 12px;\n  background: var(--surface);\n  padding: 2px 6px;\n  border-radius: 6px;\n  direction: ltr;\n  display: inline-block;\n}\n\n.md pre {\n  background: var(--code);\n  border-radius: 12px;\n  padding: 12px 14px;\n  margin: 10px 0;\n  overflow-x: auto;\n  direction: ltr;\n  text-align: left;\n}\n\n.md pre code {\n  background: none;\n  padding: 0;\n  color: var(--code-ink);\n  font-size: 12px;\n  line-height: 1.6;\n  white-space: pre;\n}\n\n/* سلسلة التفكير */\n\n.reasoning {\n  margin-bottom: 10px;\n  border-inline-start: 3px solid var(--line);\n  padding-inline-start: 10px;\n}\n\n.reasoning summary {\n  font-size: 11.5px;\n  color: var(--muted);\n  cursor: pointer;\n  list-style: none;\n}\n\n.reasoning summary::-webkit-details-marker { display: none; }\n.reasoning summary::before { content: \"▸ \"; }\n.reasoning[open] summary::before { content: \"▾ \"; }\n\n.reasoning pre {\n  margin-top: 8px;\n  font-family: var(--font);\n  font-size: 12.5px;\n  line-height: 1.65;\n  color: var(--muted);\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n/* بطاقة أداة */\n\n.tool {\n  margin: 10px 0;\n  border: 1px solid var(--line);\n  border-radius: 14px;\n  background: var(--surface);\n  overflow: hidden;\n}\n\n.tool-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 12px;\n  font-size: 12px;\n  cursor: pointer;\n  list-style: none;\n  flex-wrap: wrap;\n}\n\n.tool-head::-webkit-details-marker { display: none; }\n.tool-head .name { font-family: var(--mono); font-weight: 600; color: var(--text); }\n\n.badge {\n  font-size: 10.5px;\n  padding: 2px 8px;\n  border-radius: 20px;\n  background: var(--surface2);\n  color: var(--muted);\n}\n\n.badge.completed { background: rgba(66, 133, 244, .18); color: #8ab4f8; }\n.badge.error { background: rgba(217, 101, 112, .18); color: var(--danger); }\n.badge.running { background: rgba(155, 114, 203, .2); color: #c9a7e8; }\n\n.tool pre {\n  margin: 0;\n  padding: 10px 12px;\n  border-top: 1px solid var(--line);\n  font-family: var(--mono);\n  font-size: 11.5px;\n  line-height: 1.6;\n  white-space: pre-wrap;\n  word-break: break-word;\n  color: var(--muted);\n  direction: ltr;\n  text-align: left;\n  max-height: 320px;\n  overflow: auto;\n}\n\n.actions { display: flex; gap: 2px; margin-top: 8px; color: var(--muted); }\n\n.actions .a {\n  width: 32px;\n  height: 32px;\n  border: 0;\n  background: transparent;\n  color: inherit;\n  border-radius: 50%;\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n}\n\n.actions .a:hover { background: var(--surface); }\n.actions svg { width: 16px; height: 16px; }\n\n.typing { display: inline-flex; align-items: center; gap: 5px; color: var(--muted); font-size: 12.5px; }\n.typing i { width: 5px; height: 5px; border-radius: 50%; background: currentColor; animation: bounce 1.2s infinite; }\n.typing i:nth-child(3) { animation-delay: .15s; }\n.typing i:nth-child(4) { animation-delay: .3s; }\n@keyframes bounce { 0%, 60%, 100% { opacity: .25; transform: translateY(0); } 30% { opacity: 1; transform: translateY(-3px); } }\n\n.error-box {\n  margin-top: 10px;\n  font-size: 12.5px;\n  line-height: 1.6;\n  color: var(--danger);\n  background: rgba(217, 101, 112, .12);\n  border-inline-start: 3px solid var(--danger);\n  padding: 9px 12px;\n  border-radius: 10px;\n}\n\n/* ---------------- الأذونات ---------------- */\n\n.permissions { padding: 0 16px 8px; display: flex; flex-direction: column; gap: 8px; flex: 0 0 auto; }\n\n.permission-card {\n  background: var(--surface);\n  border: 1px solid var(--line);\n  border-radius: 14px;\n  padding: 11px 12px;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n  font-size: 12.5px;\n}\n\n.permission-card code {\n  font-family: var(--mono);\n  font-size: 11px;\n  background: var(--code);\n  color: var(--code-ink);\n  padding: 3px 7px;\n  border-radius: 6px;\n  direction: ltr;\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.btn {\n  border: 1px solid var(--line);\n  background: var(--surface2);\n  color: var(--text);\n  font: inherit;\n  font-size: 12px;\n  padding: 7px 13px;\n  border-radius: 18px;\n  cursor: pointer;\n}\n\n.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: transparent; font-weight: 600; }\n.btn.danger { background: transparent; color: var(--danger); border-color: var(--danger); }\n\n/* ---------------- شريط الإدخال ---------------- */\n\n.inputwrap { flex: 0 0 auto; padding: 8px 14px 14px; }\n\n.inputbar {\n  display: flex;\n  align-items: flex-end;\n  gap: 6px;\n  border-radius: 26px;\n  padding: 7px 8px;\n  background: var(--surface);\n}\n\n.inputbar textarea {\n  flex: 1;\n  border: 0;\n  outline: 0;\n  resize: none;\n  background: transparent;\n  color: var(--text);\n  font: inherit;\n  font-size: 14px;\n  line-height: 1.5;\n  padding: 9px 4px;\n  max-height: 180px;\n  min-height: 22px;\n}\n\n.inputbar textarea::placeholder { color: var(--muted); }\n\n.roundbtn {\n  width: 38px;\n  height: 38px;\n  border: 0;\n  border-radius: 50%;\n  background: transparent;\n  color: var(--muted);\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n  flex: 0 0 auto;\n}\n\n.roundbtn:hover { background: var(--surface2); color: var(--text); }\n\n.sendbtn { background: var(--accent); color: var(--accent-ink); }\n.sendbtn:hover { background: var(--accent); opacity: .88; }\n.sendbtn:disabled { opacity: .45; cursor: default; }\n.sendbtn svg { stroke: none; fill: currentColor; }\n.stopbtn { background: var(--surface2); color: var(--danger); }\n.stopbtn svg { fill: currentColor; stroke: none; }\n\n.disclaimer { text-align: center; font-size: 10.5px; color: var(--muted); margin-top: 9px; }\n\n/* ---------------- القائمة الجانبية ---------------- */\n\n.scrim {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, .5);\n  z-index: 40;\n  backdrop-filter: blur(2px);\n}\n\n.drawer {\n  position: fixed;\n  inset-block: 0;\n  inset-inline-start: 0;\n  width: min(300px, 84vw);\n  background: var(--bg);\n  border-inline-end: 1px solid var(--line);\n  z-index: 50;\n  display: flex;\n  flex-direction: column;\n  padding: 12px 12px 14px;\n  transform: translateX(110%);\n  transition: transform .26s ease, visibility .26s;\n  visibility: hidden;\n  overflow: hidden;\n}\n\n.drawer.open { transform: none; visibility: visible; }\n\n.dhead { display: flex; align-items: center; gap: 9px; padding: 4px 6px 14px; }\n.dhead .logo, .logo {\n  width: 30px;\n  height: 30px;\n  border-radius: 9px;\n  background: var(--grad2);\n  display: grid;\n  place-items: center;\n  flex: 0 0 auto;\n}\n.dhead .logo svg { width: 17px; height: 17px; }\n.logo.big { width: 44px; height: 44px; border-radius: 13px; margin: 0 auto; }\n.logo.big svg { width: 24px; height: 24px; }\n.dhead span { font-size: 15px; font-weight: 600; }\n.dhead b { background: var(--grad); -webkit-background-clip: text; background-clip: text; color: transparent; }\n\n.ditem {\n  display: flex;\n  align-items: center;\n  gap: 11px;\n  padding: 11px 13px;\n  border: 0;\n  background: transparent;\n  color: var(--text);\n  border-radius: 22px;\n  font: inherit;\n  font-size: 13.5px;\n  text-align: start;\n  cursor: pointer;\n  flex: 0 0 auto;\n}\n\n.ditem:hover { background: var(--surface); }\n\n.dsearch {\n  margin: 4px 4px 0;\n  padding: 9px 13px;\n  border-radius: 18px;\n  border: 1px solid var(--line);\n  background: var(--surface);\n  color: var(--text);\n  font: inherit;\n  font-size: 13px;\n  outline: none;\n}\n\n.dsection {\n  font-size: 11px;\n  color: var(--muted);\n  padding: 16px 13px 8px;\n  letter-spacing: .4px;\n}\n\n.dlist { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }\n.dlist::-webkit-scrollbar { width: 7px; }\n.dlist::-webkit-scrollbar-thumb { background: var(--line); border-radius: 8px; }\n\n.session-item {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  padding: 10px 13px;\n  border-radius: 20px;\n  cursor: pointer;\n  position: relative;\n}\n\n.session-item:hover { background: var(--surface); }\n.session-item.active { background: var(--surface2); }\n\n.session-item .t {\n  font-size: 13px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  padding-inline-end: 26px;\n}\n\n.session-item .s {\n  display: flex;\n  gap: 6px;\n  flex-wrap: wrap;\n  font-size: 10.5px;\n  color: var(--muted);\n}\n\n.session-item .tag-free { color: #4285F4; }\n\n.session-item .del {\n  position: absolute;\n  inset-inline-end: 8px;\n  top: 50%;\n  transform: translateY(-50%);\n  border: 0;\n  background: transparent;\n  color: var(--muted);\n  width: 26px;\n  height: 26px;\n  border-radius: 50%;\n  cursor: pointer;\n  opacity: 0;\n  font-size: 12px;\n}\n\n.session-item:hover .del { opacity: 1; }\n.session-item .del:hover { background: var(--surface2); color: var(--danger); }\n\n.dfooter {\n  flex: 0 0 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 10px 6px 0;\n  border-top: 1px solid var(--line);\n  margin-top: 8px;\n}\n\n.pill {\n  align-self: flex-start;\n  font-size: 11px;\n  padding: 4px 10px;\n  border-radius: 20px;\n  background: var(--surface);\n  color: var(--muted);\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.pill.ok { color: #7bd88f; }\n.pill.bad { color: var(--danger); }\n\n/* ---------------- الإعدادات ---------------- */\n\n.sheet {\n  position: fixed;\n  inset: 0;\n  z-index: 70;\n  background: var(--bg);\n  display: flex;\n  flex-direction: column;\n  transform: translateY(100%);\n  transition: transform .28s ease, visibility .28s;\n  visibility: hidden;\n  overflow: hidden;\n}\n\n.sheet.open { transform: none; visibility: visible; }\n\n/* شاشة اختيار النموذج فوق الإعدادات */\n#models { z-index: 80; }\n\n/* زر الوضع المحلي ملي يكون مسدود على سيرفر عمومي */\n.preset:disabled { opacity: .4; cursor: not-allowed; }\n\n.sheet-head {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 14px 16px 8px;\n  flex: 0 0 auto;\n}\n\n.sheet-head h2 { font-size: 19px; font-weight: 600; }\n\n.sheet-body {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 6px 20px 30px;\n  max-width: 640px;\n  width: 100%;\n  margin: 0 auto;\n}\n\n.field { margin-bottom: 16px; }\n\n.label {\n  font-size: 11.5px;\n  font-weight: 600;\n  color: var(--muted);\n  margin-bottom: 7px;\n  letter-spacing: .2px;\n}\n\n.input,\nselect,\ninput[type=\"text\"],\ninput[type=\"search\"],\ninput[type=\"password\"] {\n  width: 100%;\n  border-radius: 13px;\n  padding: 12px 14px;\n  font: inherit;\n  font-size: 13px;\n  background: var(--surface);\n  color: var(--text);\n  border: 1px solid var(--line);\n  outline: none;\n}\n\n.input.mono,\ninput[type=\"text\"] { font-family: var(--mono); font-size: 12px; }\n\n.presets { display: flex; gap: 7px; flex-wrap: wrap; }\n\n.preset {\n  font: inherit;\n  font-size: 12px;\n  padding: 8px 14px;\n  border-radius: 18px;\n  border: 1px solid var(--line);\n  background: transparent;\n  color: var(--text);\n  cursor: pointer;\n}\n\n.preset.on {\n  background: var(--accent);\n  border-color: var(--accent);\n  color: var(--accent-ink);\n  font-weight: 600;\n}\n\n.check { display: flex; align-items: center; gap: 8px; margin-top: 9px; font-size: 12px; color: var(--muted); }\n.check input { accent-color: var(--accent); width: 16px; height: 16px; }\n\n.savebtn {\n  width: 100%;\n  border: 0;\n  border-radius: 26px;\n  padding: 15px;\n  font: inherit;\n  font-size: 14px;\n  font-weight: 600;\n  background: var(--accent);\n  color: var(--accent-ink);\n  cursor: pointer;\n  margin-top: 6px;\n}\n\n.linkbtn {\n  width: 100%;\n  border: 0;\n  background: transparent;\n  color: var(--danger);\n  font: inherit;\n  font-size: 12.5px;\n  padding: 14px;\n  cursor: pointer;\n}\n\n.note {\n  margin: 6px 0 14px;\n  font-size: 11.5px;\n  line-height: 1.7;\n  color: var(--muted);\n  background: rgba(217, 101, 112, .12);\n  border-inline-start: 3px solid #D96570;\n  padding: 11px 13px;\n  border-radius: 10px;\n}\n\n.note.error { border-color: var(--danger); color: var(--danger); }\n.note code { font-family: var(--mono); direction: ltr; display: inline-block; }\n\n/* ---------------- اختيار النموذج ---------------- */\n\n.pickerbtn {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  cursor: pointer;\n  text-align: start;\n  font-family: var(--font);\n}\n\n.pickerbtn svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2.1; flex: 0 0 auto; }\n#pick-model-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n\n.mcount { font-size: 11px; margin: 12px 2px 0; }\n\n.mlist { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }\n\n.mitem {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 12px 14px;\n  border-radius: 16px;\n  background: var(--surface);\n  border: 1.5px solid transparent;\n  cursor: pointer;\n}\n\n.mitem:hover { background: var(--surface2); }\n.mitem.active { border-color: var(--accent); }\n\n.minfo { flex: 1; min-width: 0; }\n\n.mname {\n  font-size: 13.5px;\n  font-weight: 600;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.mid {\n  font-family: var(--mono);\n  font-size: 10.5px;\n  color: var(--muted);\n  direction: ltr;\n  text-align: left;\n  margin-top: 3px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.mtags { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 7px; }\n\n.mtag {\n  font-size: 10px;\n  padding: 2.5px 8px;\n  border-radius: 20px;\n  background: var(--surface2);\n  color: var(--muted);\n}\n\n.mtag.free { background: rgba(52, 168, 83, .18); color: #7bd88f; }\n.mtag.tools { background: rgba(66, 133, 244, .18); color: #8ab4f8; }\n\n.star {\n  border: 0;\n  background: transparent;\n  color: var(--muted);\n  font-size: 18px;\n  line-height: 1;\n  cursor: pointer;\n  padding: 4px 2px;\n  border-radius: 50%;\n  flex: 0 0 auto;\n}\n\n.star:hover, .star.on { color: #f5c542; }\n.mcheck { color: var(--accent); font-weight: 700; width: 16px; flex: 0 0 auto; }\n\n/* ---------------- تسجيل الدخول ---------------- */\n\n.login {\n  position: fixed;\n  inset: 0;\n  z-index: 90;\n  display: grid;\n  place-items: center;\n  background: rgba(6, 10, 16, .93);\n  backdrop-filter: blur(3px);\n  padding: 20px;\n}\n\n.login-card {\n  width: min(360px, 100%);\n  background: var(--bg);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 11px;\n}\n\n.login-card h2 { font-size: 17px; text-align: center; }\n.login-card p { text-align: center; }\n\n/* ---------------- توست ---------------- */\n\n.toast {\n  position: fixed;\n  bottom: 90px;\n  left: 50%;\n  transform: translateX(-50%);\n  background: var(--surface2);\n  color: var(--text);\n  border: 1px solid var(--line);\n  padding: 10px 18px;\n  border-radius: 22px;\n  font-size: 12.5px;\n  z-index: 95;\n  box-shadow: var(--shadow);\n}\n\n/* ---------------- موبايل صغير ---------------- */\n\n@media (max-width: 400px) {\n  .chips { grid-template-columns: 1fr; }\n  .chip { min-height: 68px; }\n  .avatar { display: none; }\n}\n","sw.js":"/**\n * sw.js — عامل الخدمة (Service Worker)\n *\n * كيخلي الموقع يتثبّت كتطبيق، وكيخلي الواجهة تحلّ بسرعة وبلا إنترنت.\n * ⚠️ ما كيكاشّش حتى طلب ديال /api/ — الدردشة خاصها الشبكة دايماً.\n */\n\nconst CACHE = \"rtlai-v1\";\nconst SHELL = [\n  \"/\",\n  \"/index.html\",\n  \"/style.css\",\n  \"/app.js\",\n  \"/manifest.webmanifest\",\n  \"/icon-192.png\",\n  \"/icon-512.png\",\n  \"/apple-touch-icon.png\",\n];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(\n    caches\n      .open(CACHE)\n      .then((c) => c.addAll(SHELL))\n      .catch(() => {})\n      .then(() => self.skipWaiting())\n  );\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches\n      .keys()\n      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))\n      .then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  const req = event.request;\n\n  if (req.method !== \"GET\") return;\n\n  let url;\n  try {\n    url = new URL(req.url);\n  } catch {\n    return;\n  }\n\n  // الأبيات: عمرو ما تتكاشّ\n  if (url.pathname.startsWith(\"/api/\")) return;\n  if (url.origin !== self.location.origin) return;\n\n  // الصفحة: الشبكة أولاً (باش تكون آخر نسخة)، والكاش كخطة ب\n  const isPage = req.mode === \"navigate\" || url.pathname === \"/\" || url.pathname.endsWith(\".html\");\n  if (isPage) {\n    event.respondWith(\n      fetch(req)\n        .then((res) => {\n          const copy = res.clone();\n          caches.open(CACHE).then((c) => c.put(\"/index.html\", copy)).catch(() => {});\n          return res;\n        })\n        .catch(() => caches.match(\"/index.html\").then((hit) => hit || caches.match(\"/\")))\n    );\n    return;\n  }\n\n  // الأصول: كاش أولاً + تحديث فالحلفية (stale-while-revalidate)\n  event.respondWith(\n    caches.match(req).then((hit) => {\n      const network = fetch(req)\n        .then((res) => {\n          if (res && res.ok) {\n            const copy = res.clone();\n            caches.open(CACHE).then((c) => c.put(req, copy)).catch(() => {});\n          }\n          return res;\n        })\n        .catch(() => hit);\n      return hit || network;\n    })\n  );\n});\n"};

/**
 * handler.js — نسخة Cloudflare Worker من الموقع
 *
 * نفس الوظيفة ديال server.mjs + direct.mjs، ولكن:
 *   • بلا خدمة opencode محلية (الوضع المحلي مطفي)
 *   • كيخدم من شبكة Cloudflare — بلا حاسوب، بلا نفق
 *   • الملفات الثابتة (index.html/style.css/app.js) كتدمج فـ build.mjs
 *
 * كيتنشر على: https://<name>.<account>.workers.dev
 */

const GATEWAY = "https://opencode.ai/inference/v1";
const VERSION = "2.0.30";
const BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
const MASK = 0xffffffffffffffffn;

// البوابة كتشيك على شكل الطلب: خاصها stream + أدوات فيها بالضبط read و bash
const GATE_TOOLS = [
  {
    type: "function",
    function: {
      name: "read",
      description: "Read the contents of a file. Returns the file content with line numbers.",
      parameters: {
        type: "object",
        properties: {
          filePath: { type: "string", description: "Absolute or workspace-relative path of the file to read." },
          offset: { type: "number", description: "1-based line to start from (optional)." },
          limit: { type: "number", description: "Maximum number of lines to read (optional)." },
        },
        required: ["filePath"],
      },
    },
  },
  {
    type: "function",
    function: {
      name: "bash",
      description: "Run a shell command inside the workspace directory and return its output.",
      parameters: {
        type: "object",
        properties: { command: { type: "string", description: "Shell command to execute." } },
        required: ["command"],
      },
    },
  },
];

const CHAT_ONLY_PROMPT = [
  "You are a language model: you can only talk. Nothing more.",
  "You have no tools, no files, no internet, no accounts and no system access. You cannot create, edit, run, download, save or execute anything,",
  "and you cannot perform any action on the user's behalf — you can only produce text.",
  "Never claim you did, made, built, searched, opened, downloaded or executed something. Never output fake tool calls, fake file contents,",
  "fake links to generated files, or fake confirmations that an action was completed. If you are unsure, say so honestly.",
  "If the user asks you to do or make something that needs an action, say clearly and briefly that you are a language model that only answers with text,",
  "then help as much as you can with words: explain, write, summarize, translate, compare, brainstorm, correct, draft text.",
  "Answer directly and conversationally, in the same language the user used. Be clear, natural and well formatted.",
].join("\n");

// ------------------------------------------------------------------ معرّفات OpenCode

function createId(descending, time = Date.now(), counter = 1) {
  let n = BigInt(time) * 0x1000n + BigInt(counter);
  if (descending) n = ~n & MASK;
  const timeBuf = new Uint8Array(8);
  new DataView(timeBuf.buffer).setBigUint64(0, n);
  const rand = new Uint8Array(14);
  crypto.getRandomValues(rand);
  let tail = "";
  for (let i = 0; i < 14; i++) tail += BASE62[rand[i] % 62];
  let hex = "";
  for (let i = 2; i < 8; i++) hex += timeBuf[i].toString(16).padStart(2, "0");
  return hex + tail;
}

const newSessionId = () => "ses_" + createId(true);
const newRequestId = () => "msg_" + createId(false);

function fingerprintHeaders(sessionID, requestID) {
  return {
    Authorization: "Bearer public",
    "Content-Type": "application/json",
    Accept: "text/event-stream",
    "User-Agent": `opencode/${VERSION}`,
    "x-opencode-client": "cli",
    "x-opencode-project": "global",
    "x-opencode-session": sessionID,
    "x-opencode-request": requestID,
  };
}

// ------------------------------------------------------------------ أدوات

const prettyName = (id) =>
  String(id)
    .replace(/-free$/, "")
    .split("-")
    .map((w) => (/^v\d/.test(w) ? w : w.length <= 2 ? w.toUpperCase() : w.charAt(0).toUpperCase() + w.slice(1)))
    .join(" ")
    .trim();

const isFree = (id) => id === "big-pickle" || id.endsWith("-free");

async function listModels() {
  const res = await fetch(`${GATEWAY}/models`, {
    headers: fingerprintHeaders(newSessionId(), newRequestId()),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const json = await res.json();
  return (json.data || [])
    .filter((m) => isFree(m.id))
    .map((m) => ({
      id: m.id,
      providerID: "opencode",
      name: prettyName(m.id),
      free: true,
      enabled: true,
      status: "active",
      context: null,
      input: ["text"],
      tools: false,
    }));
}

// ------------------------------------------------------------------ البثّ

const sse = (obj) => `data: ${JSON.stringify(obj)}\n\n`;

const SSE_HEADERS = {
  "Content-Type": "text/event-stream; charset=utf-8",
  "Cache-Control": "no-cache, no-transform",
  "X-Accel-Buffering": "no",
};

async function chat(body) {
  const model = String(body.model || "").trim();
  const messages = Array.isArray(body.messages) ? body.messages : [];
  if (!model) return json({ error: "حدد النموذج" }, 400);
  if (!messages.length) return json({ error: "لا توجد رسائل" }, 400);

  const sessionID = newSessionId();
  let upstream;
  try {
    upstream = await fetch(`${GATEWAY}/chat/completions`, {
      method: "POST",
      headers: fingerprintHeaders(sessionID, newRequestId()),
      body: JSON.stringify({
        model,
        messages: [{ role: "system", content: CHAT_ONLY_PROMPT }, ...messages],
        stream: true,
        stream_options: { include_usage: true },
        tools: GATE_TOOLS,
        tool_choice: "auto",
      }),
    });
  } catch (err) {
    return json({ error: "تعذّر الوصول للبوابة: " + err.message }, 502);
  }

  if (!upstream.ok || !upstream.body) {
    const raw = await upstream.text().catch(() => "");
    let msg = raw;
    try {
      const j = JSON.parse(raw);
      msg = j?.error?.message || j?.message || raw;
    } catch {
      /* نص عادي */
    }
    return json({ error: msg || `HTTP ${upstream.status}`, status: upstream.status }, upstream.status === 200 ? 502 : upstream.status);
  }

  const enc = new TextEncoder();
  const dec = new TextDecoder();
  const reader = upstream.body.getReader();

  const stream = new ReadableStream({
    async start(controller) {
      const send = (o) => {
        try {
          controller.enqueue(enc.encode(sse(o)));
        } catch {
          /* تسدّ */
        }
      };

      send({ type: "session", sessionID, workspace: null, chatOnly: true, tools: [] });
      send({ type: "step.start", step: 0 });

      let buf = "";
      let finish = null;
      let usage = null;
      let modelID = model;

      try {
        for (;;) {
          const { value, done } = await reader.read();
          if (done) break;
          buf += dec.decode(value, { stream: true });

          let idx;
          while ((idx = buf.indexOf("\n")) >= 0) {
            const line = buf.slice(0, idx).trim();
            buf = buf.slice(idx + 1);
            if (!line.startsWith("data:")) continue;
            const payload = line.slice(5).trim();
            if (!payload || payload === "[DONE]") continue;

            let chunk;
            try {
              chunk = JSON.parse(payload);
            } catch {
              continue;
            }
            if (chunk.model) modelID = chunk.model;
            if (chunk.usage) usage = chunk.usage;

            const choice = chunk.choices?.[0];
            if (!choice) continue;
            const delta = choice.delta || {};
            if (delta.content) send({ type: "text.delta", delta: delta.content });
            if (delta.reasoning_content) send({ type: "reasoning.delta", delta: delta.reasoning_content });
            if (choice.finish_reason) finish = choice.finish_reason;
          }
        }

        send({ type: "step.end", step: 0, finish, usage, model: modelID });
        send({ type: "done" });
      } catch (err) {
        send({ type: "error", message: err?.message || String(err) });
      } finally {
        try {
          controller.close();
        } catch {
          /* تسدّ */
        }
      }
    },
    cancel() {
      reader.cancel().catch(() => {});
    },
  });

  return new Response(stream, { status: 200, headers: SSE_HEADERS });
}

// ------------------------------------------------------------------ المساعدات

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8" },
  });
}

const TYPES = {
  html: "text/html; charset=utf-8",
  css: "text/css; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  json: "application/json; charset=utf-8",
  svg: "image/svg+xml",
  png: "image/png",
  ico: "image/x-icon",
  webmanifest: "application/manifest+json",
  txt: "text/plain; charset=utf-8",
};

function asset(pathname) {
  const clean = pathname === "/" ? "index.html" : pathname.replace(/^\/+/, "");
  let body = ASSETS[clean];
  if (body === undefined) return null;

  // الملفات الثنائية مدمجة base64 (PNG/ICO…)
  if (body && typeof body === "object" && body.__b64) {
    const bin = atob(body.__b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    body = bytes;
  }

  const ext = clean.includes(".") ? clean.split(".").pop().toLowerCase() : "html";
  return new Response(body, {
    headers: {
      "Content-Type": TYPES[ext] || "application/octet-stream",
      "Cache-Control": "no-store",
    },
  });
}

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "Content-Type",
  "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
};

function withCors(res) {
  const headers = new Headers(res.headers);
  for (const [k, v] of Object.entries(CORS)) headers.set(k, v);
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers });
}

// ------------------------------------------------------------------ الموجّه

async function handle(request) {
  const url = new URL(request.url);
  const p = url.pathname;

  if (request.method === "OPTIONS") return new Response(null, { status: 204 });

  // ---- الحالة
  if (p === "/api/health") {
    return json({
      ready: false,
      version: VERSION,
      server: "محجوب",
      location: null,
      streaming: "بلا سيرفر محلي",
      needPassword: false,
      localAvailable: false,
      direct: { base: GATEWAY, version: VERSION, tools: [], workspace: null },
      hint: "نسخة Cloudflare Worker — كتخدم بلا حاسوب.",
    });
  }

  if (p === "/api/login") return json({ ok: true, protected: false });

  // ---- الوضع المباشر
  if (p === "/api/direct/status") {
    let models = [];
    let error = null;
    try {
      models = await listModels();
    } catch (err) {
      error = err.message;
    }
    return json({
      enabled: true,
      reachable: !error,
      error,
      base: GATEWAY,
      version: VERSION,
      client: "cli",
      tools: [],
      maxSteps: 1,
      workspace: null,
      localAvailable: false,
      models: models.map((m) => m.id),
    });
  }

  if (p === "/api/direct/models") {
    try {
      return json({ models: await listModels() });
    } catch (err) {
      return json({ models: [], error: err.message }, 502);
    }
  }

  if (p === "/api/direct/chat" && request.method === "POST") {
    let body;
    try {
      body = await request.json();
    } catch {
      return json({ error: "طلب غير صالح" }, 400);
    }
    return chat(body);
  }

  // ---- أي مسار محلي = مسدود (ما كاينش سيرفر محلي)
  if (p.startsWith("/api/")) {
    return json(
      {
        localDisabled: true,
        error: "هاد النسخة كتخدم من Cloudflare — الوضع المحلي ما كاينش. استعمل الوضع «مباشر».",
      },
      403
    );
  }

  // ---- الملفات الثابتة
  const a = asset(p);
  if (a) return a;
  const fallback = asset("/");
  return fallback || new Response("ما لقيتش", { status: 404 });
}

export default {
  async fetch(request) {
    try {
      return withCors(await handle(request));
    } catch (err) {
      return withCors(json({ error: err?.message || String(err) }, 500));
    }
  },
};
